        "defaultValue": "#495057",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "progressColor": {
        "dataType": "color",
        "displayName": "Progress Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const allowMultiple = config?.allowMultiple !== false;
  const maxFiles = config?.maxFiles === 'unlimited' ? Infinity : parseInt(config?.maxFiles || '5');
  const acceptedTypes = config?.acceptedTypes || 'image/*,.pdf,.doc,.docx';
  const maxSizeMB = parseInt(config?.maxSizeMB || '10');
  const showPreviews = config?.showPreviews !== false;
  const dropzoneHeight = parseInt(config?.dropzoneHeight || '200');
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const textColor = config?.textColor || '#18181B';
  const borderColor = config?.borderColor || '#E4E4E7';
  const dragOverColor = config?.dragOverColor || '#495057';
  const accentColor = config?.accentColor || '#495057';
  const progressColor = config?.progressColor || '#495057';

  const uid = React.useMemo(() => 'fud' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const [files, setFiles] = React.useState([]);
  const [isDragOver, setIsDragOver] = React.useState(false);
  const [uploadProgress, setUploadProgress] = React.useState({});
  const [statusMessage, setStatusMessage] = React.useState('');

  const fileInputRef = React.useRef(null);
  const dragCounterRef = React.useRef(0);
  const intervalsRef = React.useRef({});

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  React.useEffect(() => {
    return () => {
      Object.values(intervalsRef.current).forEach(clearInterval);
      files.forEach(f => f.preview && URL.revokeObjectURL(f.preview));
    };
    // eslint-disable-next-line
  }, []);

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
  };

  const validateFile = (file) => {
    if (file.size > maxSizeMB * 1024 * 1024) {
      return { valid: false, error: `File exceeds ${maxSizeMB}MB limit` };
    }
    return { valid: true };
  };

  const simulateUpload = (fileId) => {
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        delete intervalsRef.current[fileId];
      }
      setUploadProgress(prev => ({ ...prev, [fileId]: progress }));
    }, 200);
    intervalsRef.current[fileId] = interval;
  };

  const handleFiles = (fileList) => {
    const newFiles = Array.from(fileList);

    if (!allowMultiple && newFiles.length > 1) {
      setStatusMessage('Only one file allowed.');
      return;
    }

    if (files.length + newFiles.length > maxFiles) {
      setStatusMessage(`Maximum ${maxFiles} files allowed.`);
      return;
    }

    const incomingFiles = newFiles.map(file => {
      const validation = validateFile(file);
      return {
        id: Math.random().toString(36).substr(2, 9),
        file,
        name: file.name,
        size: file.size,
        type: file.type,
        preview: validation.valid && file.type.startsWith('image/') ? URL.createObjectURL(file) : null,
        error: validation.valid ? null : validation.error
      };
    });

    const rejected = incomingFiles.filter(f => f.error);
    if (rejected.length > 0) {
      setStatusMessage(
        rejected.length === 1
          ? `"${rejected[0].name}" was rejected: ${rejected[0].error}.`
          : `${rejected.length} files were rejected: exceeded the ${maxSizeMB}MB limit.`
      );
    } else {
      setStatusMessage(incomingFiles.length === 1 ? `"${incomingFiles[0].name}" added.` : `${incomingFiles.length} files added.`);
    }

    incomingFiles.forEach(f => {
      if (!f.error) {
        simulateUpload(f.id);
      }
    });

    setFiles(prev => [...prev, ...incomingFiles]);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);
    dragCounterRef.current = 0;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const handleDragEnter = (e) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current++;
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      setIsDragOver(true);
    }
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current--;
    if (dragCounterRef.current === 0) {
      setIsDragOver(false);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const removeFile = (id) => {
    const removed = files.find(f => f.id === id);
    if (removed?.preview) URL.revokeObjectURL(removed.preview);
    if (intervalsRef.current[id]) {
      clearInterval(intervalsRef.current[id]);
      delete intervalsRef.current[id];
    }
    setFiles(files.filter(f => f.id !== id));
    setUploadProgress(prev => {
      const newProgress = { ...prev };
      delete newProgress[id];
      return newProgress;
    });
  };

  const getFileIcon = (type) => {
    if (type.startsWith('image/')) return '🖼️';
    if (type.includes('pdf')) return '📄';
    if (type.includes('word') || type.includes('doc')) return '📝';
    if (type.includes('sheet') || type.includes('excel')) return '📊';
    if (type.includes('video')) return '🎥';
    if (type.includes('audio')) return '🎵';
    return '📎';
  };

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <style>{`
        .${p}-dropzone:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 3px;
        }
        .${p}-remove:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 2px;
        }
        @keyframes ${p}-slideIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <div className={p} style={{ width: '100%', maxWidth: '600px' }}>
        <div
          className={`${p}-dropzone`}
          role="button"
          tabIndex={0}
          aria-label={`Upload files. ${isDragOver ? 'Drop files here' : 'Drag and drop files here, or activate to browse'}. Max ${maxFiles === Infinity ? 'unlimited' : maxFiles} files, ${maxSizeMB}MB each.`}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragEnter={handleDragEnter}
          onDragLeave={handleDragLeave}
          onClick={() => fileInputRef.current?.click()}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              fileInputRef.current?.click();
            }
          }}
          style={{
            height: `${dropzoneHeight}px`,
            border: `2px dashed ${isDragOver ? dragOverColor : borderColor}`,
            borderRadius: '12px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
            backgroundColor: isDragOver ? `${dragOverColor}10` : `${accentColor}05`,
            transition: 'border-color 300ms ease-out, background-color 300ms ease-out, transform 300ms ease-out',
            transform: prefersReducedMotion ? 'none' : (isDragOver ? 'scale(1.02)' : 'scale(1)'),
            padding: '20px'
          }}
        >
          <div style={{
            fontSize: '48px',
            marginBottom: '16px',
            opacity: isDragOver ? 1 : 0.5,
            transition: 'opacity 200ms ease-out'
          }}>
            📁
          </div>
          <div style={{
            fontSize: '16px',
            fontWeight: '500',
            color: textColor,
            marginBottom: '8px',
            textAlign: 'center'
          }}>
            {isDragOver ? 'Drop files here' : 'Drag & drop files here'}
          </div>
          <div style={{
            fontSize: '14px',
            color: accentColor,
            marginBottom: '16px',
            textAlign: 'center'
          }}>
            or click to browse
          </div>
          <div style={{
            fontSize: '13px',
            color: accentColor,
            textAlign: 'center',
            opacity: 0.7
          }}>
            Max {maxFiles === Infinity ? 'unlimited' : maxFiles} files • {maxSizeMB}MB each
          </div>
        </div>

        <input
          ref={fileInputRef}
          type="file"
          multiple={allowMultiple}
          accept={acceptedTypes}
          onChange={(e) => handleFiles(e.target.files)}
          style={{ display: 'none' }}
        />

        <div role="status" aria-live="polite" style={{
          position: 'absolute',
          width: '1px',
          height: '1px',
          overflow: 'hidden',
          clip: 'rect(0 0 0 0)',
          whiteSpace: 'nowrap'
        }}>
          {statusMessage}
        </div>

        {files.length > 0 && (
          <div style={{
            marginTop: '24px',
            display: 'flex',
            flexDirection: 'column',
            gap: '12px'
          }}>
            {files.map((file, index) => {
              const progress = uploadProgress[file.id] || 0;
              const isComplete = progress === 100;
              const hasError = !!file.error;

              return (
                <div
                  key={file.id}
                  style={{
                    padding: '16px',
                    backgroundColor: hasError ? '#E0313108' : `${accentColor}08`,
                    borderRadius: '8px',
                    border: hasError ? '1px solid #E0313140' : `1px solid ${accentColor}20`,
                    opacity: prefersReducedMotion ? 1 : 1,
                    transform: prefersReducedMotion ? 'none' : 'translateY(0)',
                    animation: prefersReducedMotion ? 'none' : `${p}-slideIn 400ms ease-out ${index * 80}ms backwards`
                  }}
                >
                  <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
                    {showPreviews && file.preview ? (
                      <img
                        src={file.preview}
                        alt={file.name}
                        style={{
                          width: '60px',
                          height: '60px',
                          objectFit: 'cover',
                          borderRadius: '6px',
                          flexShrink: 0
                        }}
                      />
                    ) : (
                      <div style={{
                        width: '60px',
                        height: '60px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '32px',
                        backgroundColor: `${accentColor}15`,
                        borderRadius: '6px',
                        flexShrink: 0
                      }}>
                        {getFileIcon(file.type)}
                      </div>
                    )}

                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{
                        fontSize: '14px',
                        fontWeight: '500',
                        color: textColor,
                        marginBottom: '4px',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap'
                      }}>
                        {file.name}
                      </div>
                      <div style={{
                        fontSize: '13px',
                        color: accentColor,
                        marginBottom: '8px'
                      }}>
                        {formatFileSize(file.size)}
                      </div>

                      {hasError ? (
                        <div role="alert" style={{
                          fontSize: '12px',
                          color: '#E03131',
                          marginTop: '4px'
                        }}>
                          {file.error}
                        </div>
                      ) : (
                        <React.Fragment>
                          <div style={{
                            height: '6px',
                            backgroundColor: `${accentColor}20`,
                            borderRadius: '3px',
                            overflow: 'hidden'
                          }}>
                            <div style={{
                              height: '100%',
                              width: `${progress}%`,
                              backgroundColor: isComplete ? '#10B981' : progressColor,
                              transition: 'width 200ms ease-out, background-color 200ms ease-out',
                              borderRadius: '3px'
                            }} />
                          </div>

                          <div style={{
                            fontSize: '12px',
                            color: accentColor,
                            marginTop: '6px'
                          }}>
                            {isComplete ? '✓ Upload complete' : `Uploading... ${Math.round(progress)}%`}
                          </div>
                        </React.Fragment>
                      )}
                    </div>

                    <button
                      className={`${p}-remove`}
                      onClick={() => removeFile(file.id)}
                      aria-label="Remove file"
                      style={{
                        background: 'none',
                        border: 'none',
                        color: accentColor,
                        cursor: 'pointer',
                        fontSize: '20px',
                        padding: '4px',
                        opacity: 0.7,
                        transition: 'opacity 200ms ease-out',
                        flexShrink: 0
                      }}
                      onMouseEnter={(e) => e.currentTarget.style.opacity = '1'}
                      onMouseLeave={(e) => e.currentTarget.style.opacity = '0.7'}
                    >
                      ×
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

interactive-searchautocomplete:
const MANIFEST = {
  "type": "Interactive.SearchAutocomplete",
  "description": "Search autocomplete with highlighted matching text, keyboard navigation, and smooth animations",
  "editorElement": {
    "selector": ".search-autocomplete",
    "displayName": "Search Autocomplete",
    "archetype": "container",
    "data": {
      "placeholder": {
        "dataType": "text",
        "displayName": "Placeholder Text",
        "defaultValue": "Search...",
        "group": "Content"
      },
      "suggestions": {
        "dataType": "text",
        "displayName": "Suggestions (comma-separated)",
        "defaultValue": "JavaScript,TypeScript,React,Vue,Angular,Svelte,Next.js,Node.js,Python,Java,C++,Ruby,Go,Rust,Swift",
        "group": "Content"
      },
      "maxResults": {
        "dataType": "select",
        "displayName": "Max Results",
        "defaultValue": "8",
        "options": ["5", "6", "8", "10", "12"],
        "group": "Content"
      },
      "showIcon": {
        "dataType": "booleanValue",
        "displayName": "Show Search Icon",
        "defaultValue": true,
        "group": "Content"
      },
      "inputWidth": {
        "dataType": "select",
        "displayName": "Input Width",
        "defaultValue": "500",
        "options": ["400", "500", "600", "700"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "borderColor": {
        "dataType": "color",
        "displayName": "Border Color",
        "defaultValue": "#E4E4E7",
        "group": "Colors"
      },
      "highlightColor": {
        "dataType": "color",
        "displayName": "Highlight Color",
        "defaultValue": "#FFC107",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "hoverColor": {
        "dataType": "color",
        "displayName": "Hover Background",
        "defaultValue": "#F8F9FA",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const placeholder = config?.placeholder || 'Search...';
  const suggestions = (config?.suggestions || 'JavaScript,TypeScript,React,Vue,Angular,Svelte,Next.js,Node.js,Python,Java,C++,Ruby,Go,Rust,Swift')
    .split(',')
    .map(s => s.trim());
  const maxResults = parseInt(config?.maxResults || '8');
  const showIcon = config?.showIcon !== false;
  const inputWidth = parseInt(config?.inputWidth || '500');
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const textColor = config?.textColor || '#18181B';
  const borderColor = config?.borderColor || '#E4E4E7';
  const highlightColor = config?.highlightColor || '#FFC107';
  const accentColor = config?.accentColor || '#495057';
  const hoverColor = config?.hoverColor || '#F8F9FA';

  const uid = React.useMemo(() => 'sac' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const [query, setQuery] = React.useState('');
  const [isOpen, setIsOpen] = React.useState(false);
  const [selectedIndex, setSelectedIndex] = React.useState(-1);
  const [isFocused, setIsFocused] = React.useState(false);

  const inputRef = React.useRef(null);
  const resultsRef = React.useRef([]);

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const filteredResults = React.useMemo(() => {
    if (!query.trim()) return [];

    const lowerQuery = query.toLowerCase();
    return suggestions
      .filter(s => s.toLowerCase().includes(lowerQuery))
      .slice(0, maxResults);
  }, [query, suggestions, maxResults]);

  const highlightMatch = (text, query) => {
    if (!query.trim()) return text;

    const parts = [];
    const lowerText = text.toLowerCase();
    const lowerQuery = query.toLowerCase();
    let lastIndex = 0;
    let index = lowerText.indexOf(lowerQuery);

    while (index !== -1) {
      if (index > lastIndex) {
        parts.push({ text: text.slice(lastIndex, index), highlight: false });
      }
      parts.push({ text: text.slice(index, index + query.length), highlight: true });
      lastIndex = index + query.length;
      index = lowerText.indexOf(lowerQuery, lastIndex);
    }

    if (lastIndex < text.length) {
      parts.push({ text: text.slice(lastIndex), highlight: false });
    }

    return parts;
  };

  const handleKeyDown = (e) => {
    if (!isOpen || filteredResults.length === 0) {
      if (e.key === 'ArrowDown') {
        setIsOpen(true);
      }
      return;
    }

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex(prev => 
          prev < filteredResults.length - 1 ? prev + 1 : prev
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex(prev => prev > 0 ? prev - 1 : -1);
        break;
      case 'Enter':
        e.preventDefault();
        if (selectedIndex >= 0) {
          selectResult(filteredResults[selectedIndex]);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        setSelectedIndex(-1);
        break;
    }
  };

  const selectResult = (result) => {
    setQuery(result);
    setIsOpen(false);
    setSelectedIndex(-1);
    inputRef.current?.blur();
  };

  React.useEffect(() => {
    if (selectedIndex >= 0 && resultsRef.current[selectedIndex]) {
      resultsRef.current[selectedIndex].scrollIntoView({
        block: 'nearest',
        behavior: 'smooth'
      });
    }
  }, [selectedIndex]);

  React.useEffect(() => {
    setIsOpen(query.trim().length > 0);
    setSelectedIndex(-1);
  }, [query, filteredResults.length]);

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <style>{`
        .${p}-clear:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { transition: none !important; }
        }
      `}</style>
      <div className={p} style={{ width: `${inputWidth}px`, maxWidth: '100%', position: 'relative' }}>
        <div style={{
          position: 'relative',
          display: 'flex',
          alignItems: 'center'
        }}>
          {showIcon && (
            <div style={{
              position: 'absolute',
              left: '16px',
              fontSize: '18px',
              color: accentColor,
              pointerEvents: 'none',
              opacity: 0.6
            }}>
              🔍
            </div>
          )}

          <input
            ref={inputRef}
            type="text"
            role="combobox"
            aria-expanded={isOpen}
            aria-autocomplete="list"
            aria-controls={`${p}-listbox`}
            aria-activedescendant={selectedIndex >= 0 ? `${p}-option-${selectedIndex}` : undefined}
            aria-label="Search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            onFocus={() => setIsFocused(true)}
            onBlur={() => {
              setTimeout(() => {
                setIsFocused(false);
                setIsOpen(false);
              }, 200);
            }}
            placeholder={placeholder}
            style={{
              width: '100%',
              padding: showIcon ? '14px 16px 14px 48px' : '14px 16px',
              fontSize: '16px',
              border: `2px solid ${isFocused ? accentColor : borderColor}`,
              borderRadius: '8px',
              outline: 'none',
              boxShadow: isFocused ? `0 0 0 3px ${accentColor}1a` : 'none',
              backgroundColor: backgroundColor,
              color: textColor,
              transition: 'border-color 200ms ease-out, box-shadow 200ms ease-out',
              fontFamily: 'inherit'
            }}
          />

          {query && (
            <button
              className={`${p}-clear`}
              aria-label="Clear search"
              onClick={() => {
                setQuery('');
                inputRef.current?.focus();
              }}
              style={{
                position: 'absolute',
                right: '12px',
                background: 'none',
                border: 'none',
                color: accentColor,
                cursor: 'pointer',
                fontSize: '20px',
                padding: '4px',
                opacity: 0.6,
                transition: 'opacity 200ms ease-out'
              }}
              onMouseEnter={(e) => e.currentTarget.style.opacity = '1'}
              onMouseLeave={(e) => e.currentTarget.style.opacity = '0.6'}
            >
              ×
            </button>
          )}
        </div>

        {isOpen && filteredResults.length > 0 && (
          <div
            id={`${p}-listbox`}
            role="listbox"
            style={{
              position: 'absolute',
              top: 'calc(100% + 8px)',
              left: 0,
              right: 0,
              backgroundColor: backgroundColor,
              border: `1px solid ${borderColor}`,
              borderRadius: '8px',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)',
              maxHeight: '320px',
              overflowY: 'auto',
              zIndex: 100,
              opacity: prefersReducedMotion ? 1 : (isOpen ? 1 : 0),
              transform: prefersReducedMotion ? 'none' : (isOpen ? 'translateY(0)' : 'translateY(-10px)'),
              transition: 'opacity 200ms ease-out, transform 200ms ease-out'
            }}>
            {filteredResults.map((result, index) => {
              const parts = highlightMatch(result, query);
              const isSelected = index === selectedIndex;

              return (
                <div
                  key={index}
                  id={`${p}-option-${index}`}
                  role="option"
                  aria-selected={isSelected}
                  ref={el => resultsRef.current[index] = el}
                  onClick={() => selectResult(result)}
                  style={{
                    padding: '12px 16px',
                    cursor: 'pointer',
                    backgroundColor: isSelected ? hoverColor : 'transparent',
                    borderLeft: isSelected ? `3px solid ${accentColor}` : '3px solid transparent',
                    transition: 'background-color 150ms ease-out, border-color 150ms ease-out',
                    fontSize: '15px',
                    color: textColor
                  }}
                  onMouseEnter={() => setSelectedIndex(index)}
                >
                  {parts.map((part, i) => (
                    <span
                      key={i}
                      style={{
                        backgroundColor: part.highlight ? `${highlightColor}40` : 'transparent',
                        fontWeight: part.highlight ? '500' : '400',
                        padding: part.highlight ? '2px 0' : '0'
                      }}
                    >
                      {part.text}
                    </span>
                  ))}
                </div>
              );
            })}
          </div>
        )}

        {query && filteredResults.length === 0 && isOpen && (
          <div role="status" aria-live="polite" style={{
            position: 'absolute',
            top: 'calc(100% + 8px)',
            left: 0,
            right: 0,
            backgroundColor: backgroundColor,
            border: `1px solid ${borderColor}`,
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)',
            padding: '20px',
            textAlign: 'center',
            color: accentColor,
            fontSize: '14px',
            zIndex: 100
          }}>
            No results found for "{query}"
          </div>
        )}

        <div style={{
          marginTop: '16px',
          fontSize: '13px',
          color: accentColor,
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}>
          <span>
            {filteredResults.length > 0 && `${filteredResults.length} result${filteredResults.length === 1 ? '' : 's'}`}
          </span>
          <span style={{ fontSize: '12px', fontStyle: 'italic' }}>
            Use ↑↓ to navigate, Enter to select
          </span>
        </div>
      </div>
    </div>
  );
}

interactive-timepicker:
const MANIFEST = {
  "type": "Interactive.TimePicker",
  "description": "Time picker with rotating hour/minute wheels, smooth scrolling, and 12/24 hour format",
  "editorElement": {
    "selector": ".time-picker",
    "displayName": "Time Picker",
    "archetype": "container",
    "data": {
      "defaultHour": {
        "dataType": "number",
        "displayName": "Default Hour",
        "defaultValue": 12,
        "group": "Content"
      },
      "defaultMinute": {
        "dataType": "number",
        "displayName": "Default Minute",
        "defaultValue": 30,
        "group": "Content"
      },
      "format24Hour": {
        "dataType": "booleanValue",
        "displayName": "24-Hour Format",
        "defaultValue": false,
        "group": "Content"
      },
      "minuteStep": {
        "dataType": "select",
        "displayName": "Minute Step",
        "defaultValue": "1",
        "options": ["1", "5", "10", "15", "30"],
        "group": "Content"
      },
      "showNowButton": {
        "dataType": "booleanValue",
        "displayName": "Show Now Button",
        "defaultValue": true,
        "group": "Content"
      },
      "wheelHeight": {
        "dataType": "select",
        "displayName": "Wheel Height",
        "defaultValue": "200",
        "options": ["150", "180", "200", "250"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "selectedColor": {
        "dataType": "color",
        "displayName": "Selected Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const defaultHour = parseInt(config?.defaultHour || '12');
  const defaultMinute = parseInt(config?.defaultMinute || '30');
  const format24Hour = config?.format24Hour === true;
  const minuteStep = parseInt(config?.minuteStep || '1');
  const showNowButton = config?.showNowButton !== false;
  const wheelHeight = parseInt(config?.wheelHeight || '200');
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const textColor = config?.textColor || '#18181B';
  const selectedColor = config?.selectedColor || '#495057';
  const accentColor = config?.accentColor || '#495057';

  const uid = React.useMemo(() => 'tmp' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const [hour, setHour] = React.useState(defaultHour);
  const [minute, setMinute] = React.useState(defaultMinute);
  const [period, setPeriod] = React.useState(defaultHour >= 12 ? 'PM' : 'AM');

  const hourRef = React.useRef(null);
  const minuteRef = React.useRef(null);

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const hours = format24Hour 
    ? Array.from({ length: 24 }, (_, i) => i)
    : Array.from({ length: 12 }, (_, i) => i + 1);

  const minutes = Array.from({ length: 60 / minuteStep }, (_, i) => i * minuteStep);

  const itemHeight = 44;
  const centerOffset = (wheelHeight - itemHeight) / 2;

  const scrollToValue = (ref, value, items) => {
    if (!ref.current) return;
    const index = items.indexOf(value);
    const scrollTop = index * itemHeight;
    ref.current.scrollTop = scrollTop;
  };

  React.useEffect(() => {
    scrollToValue(hourRef, hour, hours);
    scrollToValue(minuteRef, minute, minutes);
  }, []);

  const handleHourScroll = (e) => {
    const scrollTop = e.target.scrollTop;
    const index = Math.round(scrollTop / itemHeight);
    const newHour = hours[index];
    if (newHour !== undefined && newHour !== hour) {
      setHour(newHour);
    }
  };

  const handleMinuteScroll = (e) => {
    const scrollTop = e.target.scrollTop;
    const index = Math.round(scrollTop / itemHeight);
    const newMinute = minutes[index];
    if (newMinute !== undefined && newMinute !== minute) {
      setMinute(newMinute);
    }
  };

  const handleScrollEnd = (ref, value, items) => {
    if (!ref.current) return;
    const index = items.indexOf(value);
    const targetScroll = index * itemHeight;

    ref.current.scrollTo({
      top: targetScroll,
      behavior: prefersReducedMotion ? 'auto' : 'smooth'
    });
  };

  React.useEffect(() => {
    const hourTimer = setTimeout(() => handleScrollEnd(hourRef, hour, hours), 150);
    return () => clearTimeout(hourTimer);
  }, [hour]);

  React.useEffect(() => {
    const minuteTimer = setTimeout(() => handleScrollEnd(minuteRef, minute, minutes), 150);
    return () => clearTimeout(minuteTimer);
  }, [minute]);

  const setCurrentTime = () => {
    const now = new Date();
    let currentHour = now.getHours();
    const currentMinute = Math.floor(now.getMinutes() / minuteStep) * minuteStep;

    if (!format24Hour) {
      setPeriod(currentHour >= 12 ? 'PM' : 'AM');
      currentHour = currentHour % 12 || 12;
    }

    setHour(currentHour);
    setMinute(currentMinute);

    setTimeout(() => {
      scrollToValue(hourRef, currentHour, hours);
      scrollToValue(minuteRef, currentMinute, minutes);
    }, 50);
  };

  const formatTime = () => {
    const h = format24Hour ? hour : hour;
    const m = minute.toString().padStart(2, '0');
    return format24Hour ? `${h.toString().padStart(2, '0')}:${m}` : `${h}:${m} ${period}`;
  };

  const getOpacity = (index, selectedIndex) => {
    const distance = Math.abs(index - selectedIndex);
    if (distance === 0) return 1;
    if (distance === 1) return 0.6;
    if (distance === 2) return 0.3;
    return 0.15;
  };

  const getScale = (index, selectedIndex) => {
    const distance = Math.abs(index - selectedIndex);
    if (distance === 0) return 1;
    if (distance === 1) return 0.85;
    return 0.75;
  };

  const handleWheelKeyDown = (e, items, currentValue, setValue) => {
    const index = items.indexOf(currentValue);
    if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
      e.preventDefault();
      setValue(items[(index - 1 + items.length) % items.length]);
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
      e.preventDefault();
      setValue(items[(index + 1) % items.length]);
    } else if (e.key === 'Home') {
      e.preventDefault();
      setValue(items[0]);
    } else if (e.key === 'End') {
      e.preventDefault();
      setValue(items[items.length - 1]);
    }
  };

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <style>{`
        .${p}-wheel::-webkit-scrollbar {
          display: none;
        }
        .${p}-wheel:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 2px;
        }
        .${p}-period:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 2px;
        }
        .${p}-now:focus-visible {
          outline: 2px solid ${selectedColor};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { transition: none !important; }
        }
      `}</style>
      <div className={p} style={{
        padding: '32px',
        backgroundColor: `${accentColor}08`,
        borderRadius: '12px',
        border: `1px solid ${accentColor}20`
      }}>
        <div role="status" aria-live="polite" style={{
          fontSize: '32px',
          fontWeight: '500',
          color: textColor,
          textAlign: 'center',
          marginBottom: '24px',
          letterSpacing: '-0.02em',
          fontVariantNumeric: 'tabular-nums'
        }}>
          {formatTime()}
        </div>

        <div style={{
          display: 'flex',
          gap: '16px',
          alignItems: 'center',
          marginBottom: '24px'
        }}>
          <div style={{
            position: 'relative',
            width: '80px'
          }}>
            <div style={{
              position: 'absolute',
              top: centerOffset,
              left: 0,
              right: 0,
              height: itemHeight,
              backgroundColor: `${selectedColor}15`,
              borderRadius: '8px',
              border: `2px solid ${selectedColor}30`,
              pointerEvents: 'none',
              zIndex: 1
            }} />

            <div
              ref={hourRef}
              className={`${p}-wheel`}
              role="listbox"
              aria-label="Hour"
              tabIndex={0}
              onScroll={handleHourScroll}
              onKeyDown={(e) => handleWheelKeyDown(e, hours, hour, setHour)}
              style={{
                height: `${wheelHeight}px`,
                overflowY: 'scroll',
                scrollSnapType: 'y mandatory',
                scrollbarWidth: 'none',
                msOverflowStyle: 'none',
                position: 'relative',
                WebkitMaskImage: 'linear-gradient(to bottom, transparent, black 20%, black 80%, transparent)',
                maskImage: 'linear-gradient(to bottom, transparent, black 20%, black 80%, transparent)'
              }}
            >
              <div style={{ height: centerOffset }} />
              {hours.map((h, index) => (
                <div
                  key={h}
                  role="option"
                  aria-selected={hour === h}
                  onClick={() => {
                    setHour(h);
                    scrollToValue(hourRef, h, hours);
                  }}
                  style={{
                    height: `${itemHeight}px`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '20px',
                    fontWeight: hour === h ? '500' : '400',
                    color: hour === h ? selectedColor : textColor,
                    cursor: 'pointer',
                    scrollSnapAlign: 'start',
                    transition: 'opacity 200ms ease-out, transform 200ms ease-out, color 200ms ease-out',
                    opacity: getOpacity(index, hours.indexOf(hour)),
                    transform: prefersReducedMotion ? 'none' : `scale(${getScale(index, hours.indexOf(hour))})`,
                    fontVariantNumeric: 'tabular-nums'
                  }}
                >
                  {format24Hour ? h.toString().padStart(2, '0') : h}
                </div>
              ))}
              <div style={{ height: centerOffset }} />
            </div>
          </div>

          <div style={{
            fontSize: '24px',
            fontWeight: '500',
            color: textColor
          }}>
            :
          </div>

          <div style={{
            position: 'relative',
            width: '80px'
          }}>
            <div style={{
              position: 'absolute',
              top: centerOffset,
              left: 0,
              right: 0,
              height: itemHeight,
              backgroundColor: `${selectedColor}15`,
              borderRadius: '8px',
              border: `2px solid ${selectedColor}30`,
              pointerEvents: 'none',
              zIndex: 1
            }} />

            <div
              ref={minuteRef}
              className={`${p}-wheel`}
              role="listbox"
              aria-label="Minute"
              tabIndex={0}
              onScroll={handleMinuteScroll}
              onKeyDown={(e) => handleWheelKeyDown(e, minutes, minute, setMinute)}
              style={{
                height: `${wheelHeight}px`,
                overflowY: 'scroll',
                scrollSnapType: 'y mandatory',
                scrollbarWidth: 'none',
                msOverflowStyle: 'none',
                position: 'relative',
                WebkitMaskImage: 'linear-gradient(to bottom, transparent, black 20%, black 80%, transparent)',
                maskImage: 'linear-gradient(to bottom, transparent, black 20%, black 80%, transparent)'
              }}
            >
              <div style={{ height: centerOffset }} />
              {minutes.map((m, index) => (
                <div
                  key={m}
                  role="option"
                  aria-selected={minute === m}
                  onClick={() => {
                    setMinute(m);
                    scrollToValue(minuteRef, m, minutes);
                  }}
                  style={{
                    height: `${itemHeight}px`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '20px',
                    fontWeight: minute === m ? '500' : '400',
                    color: minute === m ? selectedColor : textColor,
                    cursor: 'pointer',
                    scrollSnapAlign: 'start',
                    transition: 'opacity 200ms ease-out, transform 200ms ease-out, color 200ms ease-out',
                    opacity: getOpacity(index, minutes.indexOf(minute)),
                    transform: prefersReducedMotion ? 'none' : `scale(${getScale(index, minutes.indexOf(minute))})`,
                    fontVariantNumeric: 'tabular-nums'
                  }}
                >
                  {m.toString().padStart(2, '0')}
                </div>
              ))}
              <div style={{ height: centerOffset }} />
            </div>
          </div>

          {!format24Hour && (
            <div role="group" aria-label="AM or PM" style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '8px'
            }}>
              {['AM', 'PM'].map(periodOption => (
                <button
                  key={periodOption}
                  className={`${p}-period`}
                  aria-pressed={period === periodOption}
                  onClick={() => setPeriod(periodOption)}
                  style={{
                    padding: '8px 12px',
                    backgroundColor: period === periodOption ? selectedColor : `${accentColor}15`,
                    color: period === periodOption ? backgroundColor : textColor,
                    border: 'none',
                    borderRadius: '6px',
                    fontSize: '14px',
                    fontWeight: '500',
                    cursor: 'pointer',
                    transition: 'background-color 200ms ease-out, color 200ms ease-out'
                  }}
                >
                  {periodOption}
                </button>
              ))}
            </div>
          )}
        </div>

        {showNowButton && (
          <button
            className={`${p}-now`}
            onClick={setCurrentTime}
            style={{
              width: '100%',
              padding: '12px',
              backgroundColor: `${selectedColor}20`,
              color: selectedColor,
              border: `1px solid ${selectedColor}30`,
              borderRadius: '8px',
              fontSize: '14px',
              fontWeight: '500',
              cursor: 'pointer',
              transition: 'background-color 200ms ease-out'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = `${selectedColor}30`;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = `${selectedColor}20`;
            }}
          >
            Set to Now
          </button>
        )}
      </div>
    </div>
  );
}

interactive-calendardatepicker:
const MANIFEST = {
  "type": "Interactive.CalendarDatePicker",
  "description": "Calendar date picker with sliding month transitions, date range selection, and keyboard navigation",
  "editorElement": {
    "selector": ".calendar-date-picker",
    "displayName": "Calendar Date Picker",
    "archetype": "container",
    "data": {
      "enableRangeSelection": {
        "dataType": "booleanValue",
        "displayName": "Enable Range Selection",
        "defaultValue": false,
        "group": "Content"
      },
      "showWeekNumbers": {
        "dataType": "booleanValue",
        "displayName": "Show Week Numbers",
        "defaultValue": false,
        "group": "Content"
      },
      "highlightToday": {
        "dataType": "booleanValue",
        "displayName": "Highlight Today",
        "defaultValue": true,
        "group": "Content"
      },
      "firstDayOfWeek": {
        "dataType": "select",
        "displayName": "First Day of Week",
        "defaultValue": "sunday",
        "options": ["sunday", "monday"],
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "selectedColor": {
        "dataType": "color",
        "displayName": "Selected Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "todayColor": {
        "dataType": "color",
        "displayName": "Today Highlight",
        "defaultValue": "#3B82F6",
        "group": "Colors"
      },
      "rangeColor": {
        "dataType": "color",
        "displayName": "Range Color",
        "defaultValue": "#E4E4E7",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const enableRangeSelection = config?.enableRangeSelection === true;
  const showWeekNumbers = config?.showWeekNumbers === true;
  const highlightToday = config?.highlightToday !== false;
  const firstDayOfWeek = config?.firstDayOfWeek || 'sunday';
  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const textColor = config?.textColor || '#18181B';
  const selectedColor = config?.selectedColor || '#495057';
  const todayColor = config?.todayColor || '#3B82F6';
  const rangeColor = config?.rangeColor || '#E4E4E7';
  const accentColor = config?.accentColor || '#495057';

  const uid = React.useMemo(() => 'cdp' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const today = new Date();
  const [currentDate, setCurrentDate] = React.useState(new Date());
  const [selectedDate, setSelectedDate] = React.useState(null);
  const [rangeStart, setRangeStart] = React.useState(null);
  const [rangeEnd, setRangeEnd] = React.useState(null);
  const [slideDirection, setSlideDirection] = React.useState('none');
  const [isAnimating, setIsAnimating] = React.useState(false);
  const [focusedDay, setFocusedDay] = React.useState(today.getDate());

  const dayButtonRefs = React.useRef({});

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const getDaysInMonth = (date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date) => {
    const day = new Date(date.getFullYear(), date.getMonth(), 1).getDay();
    return firstDayOfWeek === 'monday' ? (day === 0 ? 6 : day - 1) : day;
  };

  const getWeekNumber = (date) => {
    const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    const dayNum = d.getUTCDay() || 7;
    d.setUTCDate(d.getUTCDate() + 4 - dayNum);
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  };

  const changeMonth = (direction) => {
    if (isAnimating) return;

    setSlideDirection(direction);
    setIsAnimating(true);

    setTimeout(() => {
      const newDate = new Date(currentDate);
      newDate.setMonth(currentDate.getMonth() + (direction === 'next' ? 1 : -1));
      setCurrentDate(newDate);

      setTimeout(() => {
        setSlideDirection('none');
        setIsAnimating(false);
      }, 300);
    }, prefersReducedMotion ? 0 : 150);
  };

  const handleDateClick = (day) => {
    const clickedDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);

    if (enableRangeSelection) {
      if (!rangeStart || (rangeStart && rangeEnd)) {
        setRangeStart(clickedDate);
        setRangeEnd(null);
      } else {
        if (clickedDate < rangeStart) {
          setRangeEnd(rangeStart);
          setRangeStart(clickedDate);
        } else {
          setRangeEnd(clickedDate);
        }
      }
    } else {
      setSelectedDate(clickedDate);
    }
  };

  const isDateInRange = (day) => {
    if (!enableRangeSelection || !rangeStart) return false;
    const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
    if (!rangeEnd) return false;
    return date >= rangeStart && date <= rangeEnd;
  };

  const isDateSelected = (day) => {
    if (enableRangeSelection) {
      const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
      return (rangeStart && date.toDateString() === rangeStart.toDateString()) ||
             (rangeEnd && date.toDateString() === rangeEnd.toDateString());
    } else {
      if (!selectedDate) return false;
      return selectedDate.getDate() === day &&
             selectedDate.getMonth() === currentDate.getMonth() &&
             selectedDate.getFullYear() === currentDate.getFullYear();
    }
  };

  const isToday = (day) => {
    return today.getDate() === day &&
           today.getMonth() === currentDate.getMonth() &&
           today.getFullYear() === currentDate.getFullYear();
  };

  const monthNames = ['January', 'February', 'March', 'April', 'May', 'June',
                      'July', 'August', 'September', 'October', 'November', 'December'];

  const dayNames = firstDayOfWeek === 'monday'
    ? ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  const daysInMonth = getDaysInMonth(currentDate);
  const firstDay = getFirstDayOfMonth(currentDate);
  const weeks = Math.ceil((daysInMonth + firstDay) / 7);

  React.useEffect(() => {
    setFocusedDay(d => Math.min(Math.max(d, 1), daysInMonth));
  }, [daysInMonth]);

  React.useEffect(() => {
    dayButtonRefs.current[focusedDay]?.focus();
    // eslint-disable-next-line
  }, [focusedDay, currentDate]);

  const moveFocus = (delta) => {
    setFocusedDay(d => Math.min(Math.max(d + delta, 1), daysInMonth));
  };

  const handleGridKeyDown = (e) => {
    switch (e.key) {
      case 'ArrowRight':
        e.preventDefault();
        moveFocus(1);
        break;
      case 'ArrowLeft':
        e.preventDefault();
        moveFocus(-1);
        break;
      case 'ArrowDown':
        e.preventDefault();
        moveFocus(7);
        break;
      case 'ArrowUp':
        e.preventDefault();
        moveFocus(-7);
        break;
      case 'Home': {
        e.preventDefault();
        const dayOfWeek = (firstDay + focusedDay - 1) % 7;
        setFocusedDay(Math.max(1, focusedDay - dayOfWeek));
        break;
      }
      case 'End': {
        e.preventDefault();
        const dayOfWeek = (firstDay + focusedDay - 1) % 7;
        setFocusedDay(Math.min(daysInMonth, focusedDay + (6 - dayOfWeek)));
        break;
      }
      case 'PageUp':
        e.preventDefault();
        changeMonth('prev');
        setFocusedDay(1);
        break;
      case 'PageDown':
        e.preventDefault();
        changeMonth('next');
        setFocusedDay(1);
        break;
      default:
        break;
    }
  };

  const getSlideStyle = () => {
    if (prefersReducedMotion || slideDirection === 'none') {
      return { transform: 'translateX(0)', opacity: 1 };
    }

    if (isAnimating) {
      if (slideDirection === 'next') {
        return { transform: 'translateX(-100%)', opacity: 0 };
      } else {
        return { transform: 'translateX(100%)', opacity: 0 };
      }
    }

    return { transform: 'translateX(0)', opacity: 1 };
  };

  return (
    <div style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor: backgroundColor,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <style>{`
        .${p}-nav:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 2px;
        }
        .${p}-day:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: -2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <div className={p} style={{
        width: '360px',
        maxWidth: '100%',
        padding: '24px',
        backgroundColor: `${accentColor}08`,
        borderRadius: '12px',
        border: `1px solid ${accentColor}20`
      }}>
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '24px'
        }}>
          <button
            className={`${p}-nav`}
            onClick={() => changeMonth('prev')}
            disabled={isAnimating}
            aria-label="Previous month"
            style={{
              background: 'none',
              border: 'none',
              fontSize: '20px',
              cursor: isAnimating ? 'not-allowed' : 'pointer',
              color: textColor,
              padding: '8px',
              opacity: isAnimating ? 0.5 : 1,
              transition: 'opacity 200ms ease-out'
            }}
          >
            ←
          </button>

          <div aria-live="polite" style={{
            fontSize: '18px',
            fontWeight: '500',
            color: textColor,
            letterSpacing: '-0.01em'
          }}>
            {monthNames[currentDate.getMonth()]} {currentDate.getFullYear()}
          </div>

          <button
            className={`${p}-nav`}
            onClick={() => changeMonth('next')}
            disabled={isAnimating}
            aria-label="Next month"
            style={{
              background: 'none',
              border: 'none',
              fontSize: '20px',
              cursor: isAnimating ? 'not-allowed' : 'pointer',
              color: textColor,
              padding: '8px',
              opacity: isAnimating ? 0.5 : 1,
              transition: 'opacity 200ms ease-out'
            }}
          >
            →
          </button>
        </div>

        <div role="grid" aria-label={`${monthNames[currentDate.getMonth()]} ${currentDate.getFullYear()}`} onKeyDown={handleGridKeyDown} style={{ overflow: 'hidden' }}>
          <div style={{
            ...getSlideStyle(),
            transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
          }}>
            <div style={{
              display: 'grid',
              gridTemplateColumns: showWeekNumbers ? 'auto repeat(7, 1fr)' : 'repeat(7, 1fr)',
              gap: '4px',
              marginBottom: '8px'
            }}>
              {showWeekNumbers && <div />}
              {dayNames.map(day => (
                <div
                  key={day}
                  style={{
                    textAlign: 'center',
                    fontSize: '12px',
                    fontWeight: '500',
                    color: accentColor,
                    padding: '8px 0',
                    letterSpacing: '0.05em'
                  }}
                >
                  {day}
                </div>
              ))}
            </div>

            {Array.from({ length: weeks }, (_, weekIndex) => (
              <div
                key={weekIndex}
                style={{
                  display: 'grid',
                  gridTemplateColumns: showWeekNumbers ? 'auto repeat(7, 1fr)' : 'repeat(7, 1fr)',
                  gap: '4px',
                  marginBottom: '4px'
                }}
              >
                {showWeekNumbers && (
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '11px',
                    color: accentColor,
                    opacity: 0.5,
                    paddingRight: '8px'
                  }}>
                    {getWeekNumber(new Date(currentDate.getFullYear(), currentDate.getMonth(), weekIndex * 7 + 1 - firstDay))}
                  </div>
                )}

                {Array.from({ length: 7 }, (_, dayIndex) => {
                  const day = weekIndex * 7 + dayIndex - firstDay + 1;
                  const isValid = day > 0 && day <= daysInMonth;
                  const selected = isValid && isDateSelected(day);
                  const inRange = isValid && isDateInRange(day);
                  const todayDate = isValid && highlightToday && isToday(day);
                  const dateLabel = isValid
                    ? new Date(currentDate.getFullYear(), currentDate.getMonth(), day)
                        .toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })
                    : '';

                  return (
                    <button
                      key={dayIndex}
                      ref={(el) => { if (isValid) dayButtonRefs.current[day] = el; }}
                      tabIndex={isValid ? (day === focusedDay ? 0 : -1) : -1}
                      className={`${p}-day`}
                      aria-label={isValid ? `${dateLabel}${todayDate ? ', today' : ''}` : undefined}
                      aria-pressed={isValid ? selected : undefined}
                      aria-current={todayDate ? 'date' : undefined}
                      onClick={() => {
                        if (!isValid) return;
                        setFocusedDay(day);
                        handleDateClick(day);
                      }}
                      onFocus={() => isValid && setFocusedDay(day)}
                      disabled={!isValid}
                      style={{
                        height: '40px',
                        border: 'none',
                        borderRadius: '8px',
                        backgroundColor: selected
                          ? selectedColor
                          : inRange
                          ? rangeColor
                          : 'transparent',
                        color: selected ? backgroundColor : textColor,
                        fontSize: '14px',
                        fontWeight: selected ? '500' : '400',
                        cursor: isValid ? 'pointer' : 'default',
                        opacity: isValid ? 1 : 0,
                        transition: 'background-color 200ms ease-out, color 200ms ease-out',
                        outline: todayDate && !selected ? `2px solid ${todayColor}` : 'none',
                        outlineOffset: '-2px'
                      }}
                      onMouseEnter={(e) => {
                        if (isValid && !selected) {
                          e.currentTarget.style.backgroundColor = `${accentColor}15`;
                        }
                      }}
                      onMouseLeave={(e) => {
                        if (isValid && !selected) {
                          e.currentTarget.style.backgroundColor = inRange ? rangeColor : 'transparent';
                        }
                      }}
                    >
                      {isValid ? day : ''}
                    </button>
                  );
                })}
              </div>
            ))}
          </div>
        </div>

        {enableRangeSelection && rangeStart && rangeEnd && (
          <div style={{
            marginTop: '20px',
            padding: '12px',
            backgroundColor: `${selectedColor}15`,
            borderRadius: '8px',
            fontSize: '14px',
            color: textColor,
            textAlign: 'center'
          }}>
            {rangeStart.toLocaleDateString()} - {rangeEnd.toLocaleDateString()}
          </div>
        )}

        {!enableRangeSelection && selectedDate && (
          <div style={{
            marginTop: '20px',
            padding: '12px',
            backgroundColor: `${selectedColor}15`,
            borderRadius: '8px',
            fontSize: '14px',
            color: textColor,
            textAlign: 'center'
          }}>
            Selected: {selectedDate.toLocaleDateString()}
          </div>
        )}
      </div>
    </div>
  );
}

