        "dataType": "color",
        "displayName": "Search Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "iconColor": {
        "dataType": "color",
        "displayName": "Icon Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#212529",
        "group": "Colors"
      },
      "borderColor": {
        "dataType": "color",
        "displayName": "Border Color",
        "defaultValue": "#CED4DA",
        "group": "Colors"
      },
      "overlayColor": {
        "dataType": "color",
        "displayName": "Overlay Color",
        "defaultValue": "#000000",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "none",
      "contentResizeDirection": "none"
    }
  }
};

function Component({ config = {} }) {
  const [isExpanded, setIsExpanded] = React.useState(false);
  const [query, setQuery] = React.useState('');
  const [suggestions, setSuggestions] = React.useState([]);
  const [activeSuggestion, setActiveSuggestion] = React.useState(-1);

  const inputRef = React.useRef(null);
  const containerRef = React.useRef(null);

  const uid = React.useMemo(() => 'mso' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const expandedWidth = parseInt(config?.expandedWidth || "400");
  const iconSize = parseInt(config?.iconSize || "48");
  const mockSuggestions = ["Design System", "Data Analytics", "Dashboard Template", "Dark Mode", "Documentation"];

  React.useEffect(() => {
    if (isExpanded && inputRef.current) {
      inputRef.current.focus();
    }
    if (query.length > 0) {
      setSuggestions(mockSuggestions.filter(s => s.toLowerCase().includes(query.toLowerCase())));
    } else {
      setSuggestions([]);
    }
    setActiveSuggestion(-1);
  }, [isExpanded, query]);

  const closeSearch = () => {
    setIsExpanded(false);
    setQuery('');
    setSuggestions([]);
    setActiveSuggestion(-1);
    setTimeout(() => containerRef.current?.focus(), 0);
  };

  const selectSuggestion = (s) => {
    setQuery(s);
    setSuggestions([]);
    setActiveSuggestion(-1);
    inputRef.current?.focus();
  };

  const handleInputKeyDown = (e) => {
    if (e.key === 'Escape') {
      closeSearch();
    } else if (e.key === 'ArrowDown' && suggestions.length > 0) {
      e.preventDefault();
      setActiveSuggestion(i => (i + 1) % suggestions.length);
    } else if (e.key === 'ArrowUp' && suggestions.length > 0) {
      e.preventDefault();
      setActiveSuggestion(i => (i - 1 + suggestions.length) % suggestions.length);
    } else if (e.key === 'Enter' && activeSuggestion >= 0 && suggestions[activeSuggestion]) {
      e.preventDefault();
      selectSuggestion(suggestions[activeSuggestion]);
    }
  };

  return (
    <>
      <style>{`
        .${p}-toggle:focus-visible {
          outline: 2px solid ${config?.iconColor || '#495057'};
          outline-offset: 3px;
        }
        .${p}-clear:focus-visible {
          outline: 2px solid ${config?.iconColor || '#495057'};
          outline-offset: 2px;
        }
        @keyframes ${p}-dropIn {
          from { opacity: 0; transform: translateX(-50%) translateY(-10px); }
          to { opacity: 1; transform: translateX(-50%) translateY(0); }
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <div
        className={`morphing-search ${p}`}
        style={{
          width: '100%',
          minHeight: '600px',
          backgroundColor: config?.backgroundColor || '#F8F9FA',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontFamily: '-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif',
          position: 'relative'
        }}
      >
        <div
          ref={containerRef}
          className={`${p}-toggle`}
          role={isExpanded ? undefined : 'button'}
          tabIndex={isExpanded ? undefined : 0}
          aria-label={isExpanded ? undefined : 'Open search'}
          aria-expanded={isExpanded}
          style={{
            width: isExpanded ? `${expandedWidth}px` : `${iconSize}px`,
            height: `${iconSize}px`,
            backgroundColor: config?.searchBackground || '#FFFFFF',
            borderRadius: `${iconSize / 2}px`,
            border: `2px solid ${config?.borderColor || '#CED4DA'}`,
            display: 'flex',
            alignItems: 'center',
            padding: '0 16px',
            transition: prefersReducedMotion ? 'none' : 'width 500ms cubic-bezier(0.34,1.56,0.64,1), box-shadow 300ms ease-out',
            boxShadow: isExpanded ? '0 8px 32px rgba(0,0,0,0.12)' : '0 4px 12px rgba(0,0,0,0.08)',
            cursor: isExpanded ? 'text' : 'pointer',
            position: 'relative',
            zIndex: 1001
          }}
          onClick={() => !isExpanded && setIsExpanded(true)}
          onKeyDown={(e) => {
            if (!isExpanded && (e.key === 'Enter' || e.key === ' ')) {
              e.preventDefault();
              setIsExpanded(true);
            }
          }}
        >
          <div aria-hidden="true" style={{
            fontSize: '20px',
            color: config?.iconColor || '#495057',
            marginRight: isExpanded ? '12px' : '0',
            transition: prefersReducedMotion ? 'none' : 'margin 300ms ease-out'
          }}>
            🔍
          </div>

          {isExpanded && (
            <input
              ref={inputRef}
              type="text"
              role="combobox"
              aria-expanded={suggestions.length > 0}
              aria-controls={`${p}-listbox`}
              aria-autocomplete="list"
              aria-activedescendant={activeSuggestion >= 0 ? `${p}-option-${activeSuggestion}` : undefined}
              aria-label="Search"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search..."
              style={{
                flex: 1,
                border: 'none',
                outline: 'none',
                fontSize: '15px',
                color: config?.textColor || '#212529',
                backgroundColor: 'transparent',
                fontFamily: 'inherit'
              }}
              onKeyDown={handleInputKeyDown}
            />
          )}

          {isExpanded && (
            <button
              className={`${p}-clear`}
              aria-label="Clear search"
              onClick={(e) => {
                e.stopPropagation();
                closeSearch();
              }}
              style={{
                border: 'none',
                backgroundColor: 'transparent',
                fontSize: '20px',
                color: config?.iconColor || '#495057',
                cursor: 'pointer',
                padding: '4px',
                lineHeight: 1
              }}
            >
              ×
            </button>
          )}

          {isExpanded && suggestions.length > 0 && (
            <div
              id={`${p}-listbox`}
              role="listbox"
              style={{
                position: 'absolute',
                top: `${iconSize + 8}px`,
                left: '50%',
                transform: 'translateX(-50%)',
                width: `${expandedWidth}px`,
                backgroundColor: config?.searchBackground || '#FFFFFF',
                borderRadius: '12px',
                boxShadow: '0 12px 40px rgba(0,0,0,0.15)',
                backdropFilter: 'blur(20px)',
                overflow: 'hidden',
                zIndex: 1000,
                animation: prefersReducedMotion ? 'none' : `${p}-dropIn 300ms cubic-bezier(0.34,1.56,0.64,1)`
              }}
            >
              {suggestions.map((s, i) => (
                <div
                  key={i}
                  id={`${p}-option-${i}`}
                  role="option"
                  aria-selected={i === activeSuggestion}
                  style={{
                    padding: '16px 20px',
                    borderBottom: i < suggestions.length - 1 ? `1px solid ${config?.borderColor || '#CED4DA'}22` : 'none',
                    cursor: 'pointer',
                    transition: 'background-color 150ms ease-out',
                    color: config?.textColor || '#212529',
                    fontSize: '15px',
                    backgroundColor: i === activeSuggestion ? `${config?.borderColor || '#CED4DA'}33` : 'transparent'
                  }}
                  onMouseEnter={() => setActiveSuggestion(i)}
                  onMouseLeave={() => setActiveSuggestion(-1)}
                  onClick={() => selectSuggestion(s)}
                >
                  {s}
                </div>
              ))}
            </div>
          )}
        </div>

        {isExpanded && (
          <div
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: `${config?.overlayColor || '#000000'}20`,
              backdropFilter: 'blur(4px)',
              zIndex: 1000
            }}
            onClick={closeSearch}
          />
        )}
      </div>
    </>
  );
}

ui-formprogress:
const MANIFEST = {
  "type": "UI.FormProgress",
  "description": "Multi-step form progress with connected nodes and animated path drawing",
  "editorElement": {
    "selector": ".form-progress",
    "displayName": "Multi-Step Form Progress",
    "archetype": "container",
    "data": {
      "totalSteps": {
        "dataType": "select",
        "displayName": "Total Steps",
        "defaultValue": "5",
        "options": ["3", "4", "5", "6", "7"],
        "group": "Content"
      },
      "currentStep": {
        "dataType": "select",
        "displayName": "Current Step",
        "defaultValue": "2",
        "options": ["1", "2", "3", "4", "5", "6", "7"],
        "group": "Content"
      },
      "nodeSize": {
        "dataType": "select",
        "displayName": "Node Size",
        "defaultValue": "40",
        "options": ["32", "36", "40", "44", "48"],
        "group": "Layout"
      },
      "lineThickness": {
        "dataType": "select",
        "displayName": "Line Thickness",
        "defaultValue": "3",
        "options": ["2", "3", "4", "5"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "completedColor": {
        "dataType": "color",
        "displayName": "Completed Color",
        "defaultValue": "#28A745",
        "group": "Colors"
      },
      "currentColor": {
        "dataType": "color",
        "displayName": "Current Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "futureColor": {
        "dataType": "color",
        "displayName": "Future Color",
        "defaultValue": "#CED4DA",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#212529",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const totalSteps = parseInt(config?.totalSteps || "5");
  const requestedStep = parseInt(config?.currentStep || "2");
  const currentStep = Math.min(Math.max(requestedStep, 1), totalSteps);
  const nodeSize = parseInt(config?.nodeSize || "40");
  const lineThickness = parseInt(config?.lineThickness || "3");

  const uid = React.useMemo(() => 'fpg' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const stepLabels = ["Personal Info", "Contact", "Preferences", "Payment", "Confirmation"];
  const steps = Array.from({ length: totalSteps }, (_, i) => ({
    number: i + 1,
    label: stepLabels[i] || `Step ${i + 1}`
  }));

  const getNodeStyle = (step) => {
    const isCompleted = step < currentStep;
    const isCurrent = step === currentStep;
    let bg, color, scale, pulse;
    if (isCompleted) {
      bg = config?.completedColor || '#28A745';
      color = '#FFFFFF';
      scale = 1;
      pulse = false;
    } else if (isCurrent) {
      bg = config?.currentColor || '#495057';
      color = '#FFFFFF';
      scale = 1.15;
      pulse = true;
    } else {
      bg = config?.futureColor || '#CED4DA';
      color = config?.textColor || '#212529';
      scale = 0.9;
      pulse = false;
    }
    return {
      width: `${nodeSize}px`,
      height: `${nodeSize}px`,
      borderRadius: '50%',
      backgroundColor: bg,
      color,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: '16px',
      fontWeight: '500',
      transition: prefersReducedMotion ? 'none' : 'transform 400ms cubic-bezier(0.34,1.56,0.64,1), box-shadow 400ms ease-out',
      transform: `scale(${scale})`,
      boxShadow: isCurrent ? `0 0 0 4px ${bg}20, 0 4px 12px ${bg}40` : '0 2px 8px rgba(0,0,0,0.1)',
      animation: pulse && !prefersReducedMotion ? `${p}-pulse 2s ease-in-out infinite` : 'none',
      zIndex: 2,
      position: 'relative'
    };
  };

  return (
    <div
      className={`form-progress ${p}`}
      style={{
        width: '100%',
        minHeight: '600px',
        backgroundColor: config?.backgroundColor || '#FFFFFF',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '60px 20px',
        fontFamily: '-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif'
      }}
    >
      <style>{`
        @keyframes ${p}-pulse {
          0%, 100% { transform: scale(1.15); }
          50% { transform: scale(1.25); }
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <div style={{ maxWidth: '900px', width: '100%' }}>
        <div
          role="group"
          aria-label={`Form progress, step ${currentStep} of ${totalSteps}`}
          style={{
            position: 'relative',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: '40px'
          }}
        >
          <svg aria-hidden="true" style={{
            position: 'absolute',
            top: '50%',
            left: 0,
            right: 0,
            height: `${lineThickness}px`,
            transform: 'translateY(-50%)',
            zIndex: 1,
            pointerEvents: 'none'
          }}>
            <line x1="5%" y1="50%" x2="95%" y2="50%" stroke={config?.futureColor || '#CED4DA'} strokeWidth={lineThickness} />
            <line
              x1="5%"
              y1="50%"
              x2={`${5 + (90 / totalSteps) * (currentStep - 1)}%`}
              y2="50%"
              stroke={config?.completedColor || '#28A745'}
              strokeWidth={lineThickness}
              strokeLinecap="round"
              style={{ transition: prefersReducedMotion ? 'none' : 'x2 600ms cubic-bezier(0.22,1,0.36,1)' }}
            />
          </svg>
          {steps.map((step, i) => {
            const isCompleted = step.number < currentStep;
            const isCurrent = step.number === currentStep;
            const stateLabel = isCompleted ? 'completed' : isCurrent ? 'current' : 'upcoming';
            return (
              <div
                key={i}
                aria-label={`Step ${step.number}: ${step.label}, ${stateLabel}`}
                aria-current={isCurrent ? 'step' : undefined}
                style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px', flex: 1 }}
              >
                <div aria-hidden="true" style={getNodeStyle(step.number)}>
                  {step.number < currentStep ? '✓' : step.number}
                </div>
                <div aria-hidden="true" style={{
                  fontSize: '13px',
                  color: config?.textColor || '#212529',
                  fontWeight: step.number === currentStep ? '500' : '400',
                  opacity: step.number <= currentStep ? 1 : 0.5,
                  transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out',
                  textAlign: 'center',
                  maxWidth: '80px'
                }}>
                  {step.label}
                </div>
              </div>
            );
          })}
        </div>
        <div style={{
          backgroundColor: '#F8F9FA',
          borderRadius: '12px',
          padding: '32px',
          textAlign: 'center',
          boxShadow: 'inset 0 2px 8px rgba(0,0,0,0.04)'
        }}>
          <h3 role="status" aria-live="polite" style={{ fontSize: '20px', fontWeight: '500', color: config?.textColor || '#212529', margin: '0 0 8px 0' }}>
            Step {currentStep}: {steps[currentStep - 1].label}
          </h3>
          <p style={{ fontSize: '14px', color: config?.textColor || '#212529', opacity: 0.7, margin: 0 }}>
            Complete this step to continue
          </p>
        </div>
      </div>
    </div>
  );
}

