  "type": "UI.Card3DStack",
  "description": "3D card stack carousel that fans on hover and brings clicked card to front",
  "editorElement": {
    "selector": ".card-3d-stack",
    "displayName": "3D Card Stack Carousel",
    "archetype": "container",
    "data": {
      "cardCount": {
