        "displayName": "Fan Angle (degrees)",
        "defaultValue": "15",
        "options": ["10", "15", "20", "25"],
        "group": "Animation"
      },
      "depthOffset": {
        "dataType": "select",
        "displayName": "Depth Offset",
        "defaultValue": "40",
        "options": ["30", "35", "40", "45", "50"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "cardBackground": {
        "dataType": "color",
        "displayName": "Card Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#212529",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#495057",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [isFanned, setIsFanned] = React.useState(false);
  const [activeIndex, setActiveIndex] = React.useState(0);

  const uid = React.useMemo(() => 'c3d' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const cardRefs = React.useRef([]);

  const cardCount = parseInt(config?.cardCount || "5");
  const fanAngle = parseInt(config?.fanAngle || "15");
  const depthOffset = parseInt(config?.depthOffset || "40");

  const split = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
  const titleList = split(config?.cardTitles || 'Brand Refresh,Mobile App Redesign,E-commerce Migration,Dashboard Overhaul,Marketing Site Rebuild,Internal Tools Revamp,Platform Modernization');
  const descList = String(config?.cardDescriptions || 'Modernized visual identity across every touchpoint;Streamlined checkout flow for mobile shoppers;Zero-downtime migration to a headless storefront;Real-time analytics surfaced for the ops team;Faster load times and a sharper story;Replaced legacy scripts with a unified toolkit;Rebuilt core services for scale')
    .split(';').map((x) => x.trim()).filter(Boolean);
  const picsumIds = [1015, 1025, 1033, 1043, 1053, 1062, 1074];

  const cards = Array.from({ length: cardCount }, (_, i) => ({
    title: titleList[i] || `Project ${i + 1}`,
    desc: descList[i] || 'Innovative solution for modern challenges',
    image: `https://picsum.photos/id/${picsumIds[i % picsumIds.length]}/600/400`
  }));

  const getCardStyle = (index) => {
    const isActive = index === activeIndex;
    const position = index - activeIndex;
    if (isActive) {
      return { transform: 'translateZ(0px) rotateY(0deg) scale(1)', zIndex: 100, opacity: 1 };
    }
    if (isFanned) {
      const angle = position * fanAngle;
      const z = Math.abs(position) * -depthOffset;
      return {
        transform: `translateZ(${z}px) rotateY(${angle}deg) scale(${1 - Math.abs(position) * 0.1})`,
        zIndex: 50 - Math.abs(position),
        opacity: 1
      };
    }
    const z = position * -20;
    return {
      transform: `translateZ(${z}px) scale(${1 - Math.abs(position) * 0.05})`,
      zIndex: 50 - Math.abs(position),
      opacity: position <= 0 ? 1 : 0.5
    };
  };

  const focusCard = (index) => {
    const clamped = (index + cardCount) % cardCount;
    setActiveIndex(clamped);
    cardRefs.current[clamped]?.focus();
  };

  const handleCardKeyDown = (e, i) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      setActiveIndex(i);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      focusCard(i + 1);
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      focusCard(i - 1);
    }
  };

  return (
    <div
      className={`card-3d-stack ${p}`}
      role="group"
      aria-label="Project card stack"
      style={{
        width: '100%',
        minHeight: '800px',
        backgroundColor: config?.backgroundColor || '#18181B',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily: '-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif',
        padding: '60px 20px',
        perspective: '1200px'
      }}
      onMouseEnter={() => setIsFanned(true)}
      onMouseLeave={() => setIsFanned(false)}
      onFocus={() => setIsFanned(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setIsFanned(false);
      }}
    >
      <style>{`
        .${p}-card:focus-visible {
          outline: 3px solid ${config?.accentColor || '#495057'};
          outline-offset: 4px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { transition: none !important; }
        }
      `}</style>
      <div style={{ position: 'relative', width: '400px', height: '500px', transformStyle: 'preserve-3d' }}>
        {cards.map((card, i) => (
          <div
            key={i}
            ref={(el) => { cardRefs.current[i] = el; }}
            className={`${p}-card`}
            role="button"
            tabIndex={0}
            aria-label={`${card.title}, card ${i + 1} of ${cardCount}${i === activeIndex ? ', active' : ''}`}
            aria-current={i === activeIndex}
            onClick={() => setActiveIndex(i)}
            onKeyDown={(e) => handleCardKeyDown(e, i)}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              backgroundColor: config?.cardBackground || '#FFFFFF',
              borderRadius: '16px',
              overflow: 'hidden',
              cursor: 'pointer',
              transition: prefersReducedMotion ? 'none' : 'transform 600ms cubic-bezier(0.34,1.56,0.64,1), opacity 600ms ease-out',
              transformStyle: 'preserve-3d',
              boxShadow: '0 20px 60px rgba(0,0,0,0.4)',
              border: `1px solid ${config?.accentColor || '#495057'}22`,
              ...getCardStyle(i)
            }}
          >
            <img src={card.image} alt={card.title} style={{ width: '100%', height: '70%', objectFit: 'cover' }} />
            <div style={{ padding: '20px', color: config?.textColor || '#212529' }}>
              <h3 style={{ fontSize: '20px', fontWeight: '500', margin: '0 0 8px 0', letterSpacing: '-0.01em' }}>{card.title}</h3>
              <p style={{ fontSize: '14px', opacity: 0.7, margin: 0, lineHeight: 1.5 }}>{card.desc}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

