      aspectRatio: config?.cardAspectRatio || '1/1',
      objectFit: 'cover'
    },
    cardContent: {
      padding: '20px'
    },
    cardTitle: {
      fontSize: config?.titleSize || '16px',
      fontWeight: '500',
      color: config?.primaryTextColor || '#1A1A1A',
      marginBottom: '8px',
      lineHeight: '1.4'
    },
    cardDescription: {
      fontSize: '14px',
      color: config?.secondaryTextColor || '#6B6B6B',
      marginBottom: '12px',
      lineHeight: '1.6'
    },
    cardFooter: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center'
    },
    price: {
      fontSize: config?.priceSize || '20px',
      fontWeight: '500',
      color: config?.primaryTextColor || '#1A1A1A'
    },
    rating: {
      display: 'flex',
      alignItems: 'center',
      gap: '6px',
      fontSize: '14px',
      color: config?.secondaryTextColor || '#6B6B6B'
    },
    star: {
      color: config?.starColor || '#F59E0B'
    }
  };

  return (
    <div style={styles.container} className={`advanced-search-container ${p}`}>
      <style>{`
        .${p}-btn:focus-visible, .${p}-input:focus-visible, .${p}-select:focus-visible {
          outline: 2px solid ${config?.accentColor || '#1A1A1A'};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <aside style={styles.sidebar}>
        <div style={styles.searchBox}>
          <input
            type="text"
            className={`${p}-input`}
            placeholder={config?.searchPlaceholder || 'Search products...'}
            aria-label={config?.searchPlaceholder || 'Search products...'}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={styles.searchInput}
            onFocus={(e) => {
              e.target.style.borderColor = config?.accentColor || '#1A1A1A';
            }}
            onBlur={(e) => {
              e.target.style.borderColor = config?.borderColor || 'rgba(0,0,0,0.08)';
            }}
          />
        </div>

        <div style={styles.filterSection}>
          <div style={styles.filterTitle}>Category</div>
          {categories.map((category) => (
            <button
              key={category}
              className={`${p}-btn`}
              aria-pressed={activeCategory === category}
              style={{
                ...styles.filterOption,
                ...(activeCategory === category ? styles.filterOptionActive : {})
              }}
              onClick={() => setActiveCategory(category)}
              onMouseEnter={(e) => {
                if (activeCategory !== category) {
                  e.currentTarget.style.backgroundColor = 'rgba(0,0,0,0.03)';
                }
              }}
              onMouseLeave={(e) => {
                if (activeCategory !== category) {
                  e.currentTarget.style.backgroundColor = 'transparent';
                }
              }}
            >
              {category}
            </button>
          ))}
        </div>

        <div style={styles.filterSection}>
          <div style={styles.filterTitle}>Price Range</div>
          {priceRanges.map((range, index) => (
            <button
              key={index}
              className={`${p}-btn`}
              aria-pressed={activePriceRange === index}
              style={{
                ...styles.filterOption,
                ...(activePriceRange === index ? styles.filterOptionActive : {})
              }}
              onClick={() => setActivePriceRange(index)}
              onMouseEnter={(e) => {
                if (activePriceRange !== index) {
                  e.currentTarget.style.backgroundColor = 'rgba(0,0,0,0.03)';
                }
              }}
              onMouseLeave={(e) => {
                if (activePriceRange !== index) {
                  e.currentTarget.style.backgroundColor = 'transparent';
                }
              }}
            >
              {range.label}
            </button>
          ))}
        </div>

        <div style={styles.filterSection}>
          <div style={styles.filterTitle}>Minimum Rating</div>
          <div style={styles.ratingFilter}>
            {[4, 3, 2, 1, 0].map((rating) => (
              <button
                key={rating}
                type="button"
                className={`${p}-btn`}
                aria-pressed={minRating === rating}
                aria-label={rating === 0 ? 'All ratings' : `${rating} stars and up`}
                style={{
                  ...styles.ratingOption,
                  border: 'none',
                  textAlign: 'left',
                  font: 'inherit',
                  color: config?.starColor || '#F59E0B',
                  ...(minRating === rating ? { backgroundColor: 'rgba(0,0,0,0.03)' } : {})
                }}
                onClick={() => setMinRating(rating)}
                onMouseEnter={(e) => {
                  e.currentTarget.style.backgroundColor = 'rgba(0,0,0,0.03)';
                }}
                onMouseLeave={(e) => {
                  if (minRating !== rating) {
                    e.currentTarget.style.backgroundColor = 'transparent';
                  }
                }}
              >
                {rating === 0 ? (
                  <span style={{fontSize: '14px', color: config?.primaryTextColor || '#1A1A1A'}}>All Ratings</span>
                ) : (
                  <>
                    {'★'.repeat(rating)}
                    <span style={{fontSize: '14px', color: config?.secondaryTextColor || '#6B6B6B'}}>& Up</span>
                  </>
                )}
              </button>
            ))}
          </div>
        </div>
      </aside>

      <main style={styles.main}>
        <div style={styles.header}>
          {(config?.showResults !== false) && (
            <div style={styles.resultsCount}>
              {filteredItems.length} {filteredItems.length === 1 ? 'result' : 'results'}
            </div>
          )}
          <select
            className={`${p}-select`}
            aria-label="Sort by"
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            style={styles.sortSelect}
          >
            {sortOptions.map((option) => (
              <option key={option} value={option}>{option}</option>
            ))}
          </select>
        </div>

        {filteredItems.length === 0 ? (
          <div role="status" style={{
            padding: '64px 24px',
            textAlign: 'center',
            color: config?.secondaryTextColor || '#6B6B6B',
            fontSize: '14px'
          }}>
            No results match your filters. Try broadening your search.
          </div>
        ) : (
        <div style={styles.grid}>
          {filteredItems.map((item, index) => (
            <div
              key={item.id}
              ref={el => cardRefs.current[index] = el}
              style={styles.card}
              onMouseEnter={(e) => {
                if (!prefersReducedMotion) e.currentTarget.style.transform = 'translateY(-4px)';
                e.currentTarget.style.boxShadow = (config?.showShadow !== false) ? '0 8px 24px rgba(0,0,0,0.08)' : 'none';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = (config?.showShadow !== false) ? '0 2px 8px rgba(0,0,0,0.04)' : 'none';
              }}
            >
              <img src={item.image} alt={item.title} style={styles.cardImage} />
              <div style={styles.cardContent}>
                <h3 style={styles.cardTitle}>{item.title}</h3>
                <p style={styles.cardDescription}>{item.description}</p>
                <div style={styles.cardFooter}>
                  <span style={styles.price}>${item.price}</span>
                  <div style={styles.rating}>
                    <span style={styles.star}>★</span>
                    <span>{item.rating}</span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
        )}
      </main>
    </div>
  );
}

