    },
    label: {
      fontSize: config?.labelSize || '14px',
      fontWeight: '500',
      color: config?.primaryTextColor || '#1A1A1A',
      display: 'flex',
      alignItems: 'center',
      gap: '4px'
    },
    required: {
      color: config?.errorColor || '#EF4444'
    },
    input: {
      width: '100%',
      padding: '12px 16px',
      fontSize: '14px',
      color: config?.primaryTextColor || '#1A1A1A',
      backgroundColor: config?.formBackgroundColor || '#FFFFFF',
      border: `1px solid ${config?.borderColor || 'rgba(0,0,0,0.08)'}`,
      borderRadius: config?.borderRadius || '8px',
      outline: 'none',
      transition: `all ${transitionDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`,
      fontFamily: 'inherit'
    },
    inputError: {
      borderColor: config?.errorColor || '#EF4444'
    },
    error: {
      fontSize: '12px',
      color: config?.errorColor || '#EF4444',
      marginTop: '4px'
    },
    checkboxContainer: {
      display: 'flex',
      alignItems: 'center',
      gap: '12px'
    },
    checkbox: {
      width: '20px',
      height: '20px',
      cursor: 'pointer',
      accentColor: config?.accentColor || '#1A1A1A'
    },
    checkboxLabel: {
      fontSize: '14px',
      color: config?.primaryTextColor || '#1A1A1A',
      cursor: 'pointer',
      userSelect: 'none'
    },
    buttonContainer: {
      display: 'flex',
      gap: '12px',
      marginTop: '32px'
    },
    button: {
      flex: '1',
      padding: '14px 24px',
      fontSize: '16px',
      fontWeight: '500',
      border: 'none',
      borderRadius: config?.borderRadius || '8px',
      cursor: 'pointer',
      transition: `all ${transitionDuration}ms cubic-bezier(0.4, 0, 0.2, 1)`,
      outline: 'none'
    },
    buttonPrimary: {
      backgroundColor: config?.accentColor || '#1A1A1A',
      color: '#FFFFFF'
    },
    buttonSecondary: {
      backgroundColor: 'transparent',
      color: config?.secondaryTextColor || '#6B6B6B',
      border: `1px solid ${config?.borderColor || 'rgba(0,0,0,0.08)'}`
    },
    successContainer: {
      textAlign: 'center',
      padding: '48px 24px'
    },
    successIcon: {
      width: '64px',
      height: '64px',
      margin: '0 auto 24px',
      color: config?.successColor || '#10B981'
    },
    successTitle: {
      fontSize: '24px',
      fontWeight: '500',
      color: config?.primaryTextColor || '#1A1A1A',
      marginBottom: '12px'
    },
    successMessage: {
      fontSize: '16px',
      color: config?.secondaryTextColor || '#6B6B6B',
      lineHeight: '1.6'
    }
  };

  if (isSubmitted) {
    return (
      <div style={styles.container} className={`multistep-form-container ${p}`}>
        <div style={styles.form}>
          <div role="status" style={styles.successContainer}>
            <svg aria-hidden="true" style={styles.successIcon} viewBox="0 0 64 64" fill="none">
              <circle cx="32" cy="32" r="30" stroke="currentColor" strokeWidth="3" />
              <path d="M20 32l8 8 16-16" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            <div style={styles.successTitle}>Success!</div>
            <div style={styles.successMessage}>
              {config?.successMessage || 'Setup complete! Welcome aboard.'}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container} className={`multistep-form-container ${p}`}>
      <style>{`
        .${p}-btn:focus-visible, .${p}-input:focus-visible, .${p}-select:focus-visible, .${p}-checkbox:focus-visible {
          outline: 2px solid ${config?.accentColor || '#1A1A1A'};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <div style={styles.form}>
        <div style={styles.progressContainer}>
          <div role="group" aria-label={`Step ${currentStep + 1} of ${steps.length}`} style={styles.progressSteps}>
            {steps.map((step, index) => (
              <div
                key={index}
                aria-current={index === currentStep ? 'step' : undefined}
                aria-label={`${step.title}${index < currentStep ? ', completed' : index === currentStep ? ', current' : ''}`}
                style={styles.progressStep}
              >
                <div aria-hidden="true" style={{
                  ...styles.progressStepNumber,
                  ...(index === currentStep ? styles.progressStepNumberActive : {}),
                  ...(index < currentStep ? styles.progressStepNumberCompleted : {})
                }}>
                  {index < currentStep ? '✓' : index + 1}
                </div>
                <div style={styles.progressStepLabel}>{step.title}</div>
              </div>
            ))}
          </div>
          <div style={styles.progressBar}>
            <div style={{...styles.progressBarFill, width: `${progress}%`}} />
          </div>
        </div>

        <div ref={contentRef} style={styles.stepContent}>
          <h2 style={styles.stepTitle}>{currentStepData.title}</h2>
          <p style={styles.stepDescription}>{currentStepData.description}</p>

          <div style={styles.fieldsContainer}>
            {currentStepData.fields.map((field, idx) => (
              <div key={idx} style={styles.fieldGroup}>
                {field.type !== 'checkbox' && (
                  <label style={styles.label} htmlFor={field.name}>
                    {field.label}
                    {field.required && <span style={styles.required}>*</span>}
                  </label>
                )}

                {field.type === 'text' || field.type === 'email' ? (
                  <>
                    <input
                      id={field.name}
                      className={`${p}-input`}
                      type={field.type}
                      value={formData[field.name] || ''}
                      onChange={(e) => handleFieldChange(field.name, e.target.value)}
                      aria-invalid={!!errors[field.name]}
                      aria-describedby={errors[field.name] ? `${field.name}-error` : undefined}
                      style={{
                        ...styles.input,
                        ...(errors[field.name] ? styles.inputError : {})
                      }}
                      onFocus={(e) => {
                        e.target.style.borderColor = config?.accentColor || '#1A1A1A';
                      }}
                      onBlur={(e) => {
                        e.target.style.borderColor = errors[field.name]
                          ? (config?.errorColor || '#EF4444')
                          : (config?.borderColor || 'rgba(0,0,0,0.08)');
                      }}
                    />
                    {errors[field.name] && <span id={`${field.name}-error`} role="alert" style={styles.error}>{errors[field.name]}</span>}
                  </>
                ) : field.type === 'select' ? (
                  <>
                    <select
                      id={field.name}
                      className={`${p}-select`}
                      value={formData[field.name] || ''}
                      onChange={(e) => handleFieldChange(field.name, e.target.value)}
                      aria-invalid={!!errors[field.name]}
                      aria-describedby={errors[field.name] ? `${field.name}-error` : undefined}
                      style={{
                        ...styles.input,
                        ...(errors[field.name] ? styles.inputError : {})
                      }}
                      onFocus={(e) => {
                        e.target.style.borderColor = config?.accentColor || '#1A1A1A';
                      }}
                      onBlur={(e) => {
                        e.target.style.borderColor = errors[field.name]
                          ? (config?.errorColor || '#EF4444')
                          : (config?.borderColor || 'rgba(0,0,0,0.08)');
                      }}
                    >
                      <option value="">Select {field.label}</option>
                      {field.options.map((opt, i) => (
                        <option key={i} value={opt}>{opt}</option>
                      ))}
                    </select>
                    {errors[field.name] && <span id={`${field.name}-error`} role="alert" style={styles.error}>{errors[field.name]}</span>}
                  </>
                ) : field.type === 'checkbox' ? (
                  <>
                    <div style={styles.checkboxContainer}>
                      <input
                        id={field.name}
                        className={`${p}-checkbox`}
                        type="checkbox"
                        checked={formData[field.name] || false}
                        onChange={(e) => handleFieldChange(field.name, e.target.checked)}
                        aria-invalid={!!errors[field.name]}
                        aria-describedby={errors[field.name] ? `${field.name}-error` : undefined}
                        style={styles.checkbox}
                      />
                      <label htmlFor={field.name} style={styles.checkboxLabel}>
                        {field.label}
                        {field.required && <span style={styles.required}> *</span>}
                      </label>
                    </div>
                    {errors[field.name] && <span id={`${field.name}-error`} role="alert" style={styles.error}>{errors[field.name]}</span>}
                  </>
                ) : null}
              </div>
            ))}
          </div>
        </div>

        <div style={styles.buttonContainer}>
          {currentStep > 0 && (
            <button
              className={`${p}-btn`}
              style={{...styles.button, ...styles.buttonSecondary}}
              onClick={handlePrevious}
              onMouseEnter={(e) => {
                e.currentTarget.style.backgroundColor = 'rgba(0,0,0,0.03)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.backgroundColor = 'transparent';
              }}
            >
              Previous
            </button>
          )}
          {currentStep < steps.length - 1 ? (
            <button
              className={`${p}-btn`}
              style={{...styles.button, ...styles.buttonPrimary}}
              onClick={handleNext}
              onMouseEnter={(e) => {
                if (!prefersReducedMotion) e.currentTarget.style.transform = 'scale(1.02)';
                e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'scale(1)';
                e.currentTarget.style.boxShadow = 'none';
              }}
            >
              Continue
            </button>
          ) : (
            <button
              className={`${p}-btn`}
              style={{...styles.button, ...styles.buttonPrimary}}
              onClick={handleSubmit}
              onMouseEnter={(e) => {
                if (!prefersReducedMotion) e.currentTarget.style.transform = 'scale(1.02)';
                e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'scale(1)';
                e.currentTarget.style.boxShadow = 'none';
              }}
            >
              {config?.submitButtonText || 'Complete Setup'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

editor-markdowneditor:
const MANIFEST = {
  "type": "Editor.MarkdownEditor",
  "description": "Professional markdown editor with live preview featuring split-pane layout, syntax highlighting, and real-time rendering. Ideal for documentation, blog posts, and technical writing.",
  "editorElement": {
    "selector": ".markdown-editor",
    "displayName": "Markdown Editor",
    "archetype": "container",
    "data": {
      "placeholderText": {
        "dataType": "text",
        "displayName": "Placeholder Text",
        "defaultValue": "Start writing in markdown...",
        "group": "Content"
      },
      "defaultContent": {
        "dataType": "text",
        "displayName": "Default Content",
        "defaultValue": "# Welcome to Markdown Editor\n\nStart writing your **markdown** content here.\n\n## Features\n- Real-time preview\n- Clean interface\n- Easy to use",
        "group": "Content"
      },
      "showToolbar": {
        "dataType": "booleanValue",
        "displayName": "Show Toolbar",
        "defaultValue": true,
        "group": "Content"
      },
      "editorBackground": {
        "dataType": "color",
        "displayName": "Editor Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "previewBackground": {
        "dataType": "color",
        "displayName": "Preview Background",
        "defaultValue": "#FAFBFC",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#1F2937",
        "group": "Colors"
      },
      "borderColor": {
        "dataType": "color",
        "displayName": "Border Color",
        "defaultValue": "#E5E7EB",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#3B82F6",
        "group": "Colors"
      },
      "editorFontSize": {
        "dataType": "number",
        "displayName": "Editor Font Size (px)",
        "defaultValue": 15,
        "group": "Typography"
      },
      "previewFontSize": {
        "dataType": "number",
        "displayName": "Preview Font Size (px)",
        "defaultValue": 16,
        "group": "Typography"
      },
      "lineHeight": {
        "dataType": "select",
        "displayName": "Line Height",
        "defaultValue": "1.6",
        "options": ["1.4", "1.6", "1.8"],
        "group": "Typography"
      },
      "editorPadding": {
        "dataType": "number",
        "displayName": "Editor Padding (px)",
        "defaultValue": 24,
        "group": "Layout"
      },
      "previewPadding": {
        "dataType": "number",
        "displayName": "Preview Padding (px)",
        "defaultValue": 32,
        "group": "Layout"
      },
      "minHeight": {
        "dataType": "number",
        "displayName": "Minimum Height (px)",
        "defaultValue": 500,
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const placeholderText = config?.placeholderText || "Start writing in markdown...";
  const defaultContent = config?.defaultContent || "# Welcome to Markdown Editor\n\nStart writing your **markdown** content here.\n\n## Features\n- Real-time preview\n- Clean interface\n- Easy to use";
  const showToolbar = config?.showToolbar !== false;
  const editorBackground = config?.editorBackground || "#FFFFFF";
  const previewBackground = config?.previewBackground || "#FAFBFC";
  const textColor = config?.textColor || "#1F2937";
  const borderColor = config?.borderColor || "#E5E7EB";
  const accentColor = config?.accentColor || "#3B82F6";
  const editorFontSize = parseInt(config?.editorFontSize || "15");
  const previewFontSize = parseInt(config?.previewFontSize || "16");
  const lineHeight = config?.lineHeight || "1.6";
  const editorPadding = parseInt(config?.editorPadding || "24");
  const previewPadding = parseInt(config?.previewPadding || "32");
  const minHeight = parseInt(config?.minHeight || "500");

  const [markdown, setMarkdown] = React.useState(defaultContent);
  const [isFocused, setIsFocused] = React.useState(false);
  const textareaRef = React.useRef(null);

  const uid = React.useMemo(() => 'mde' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  // Lightweight syntax highlighter for fenced code blocks
  const highlightCode = (code) => {
    const escaped = code.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const tokenPattern = /(\/\/[^\n]*|#[^\n]*)|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`)|(\b\d+(?:\.\d+)?\b)/g;
    const withTokens = escaped.replace(tokenPattern, (match, comment, string, number) => {
      if (comment) return `<span style="color:#9CA3AF;font-style:italic;">${comment}</span>`;
      if (string) return `<span style="color:#10B981;">${string}</span>`;
      if (number) return `<span style="color:#F59E0B;">${number}</span>`;
      return match;
    });
    const keywords = /\b(const|let|var|function|return|if|else|for|while|class|import|export|from|new|this|true|false|null|undefined|def|async|await|try|catch)\b/g;
    return withTokens.replace(keywords, (m) => `<span style="color:${accentColor};font-weight:600;">${m}</span>`);
  };

  // Simple markdown parser
  const parseMarkdown = (text) => {
    let html = text;

    // Fenced code blocks (with lightweight syntax highlighting)
    html = html.replace(/```([a-z]*)\n([\s\S]*?)```/gim, (match, lang, code) => {
      return `<pre><code>${highlightCode(code)}</code></pre>`;
    });

    // Inline code
    html = html.replace(/`([^`\n]+)`/g, '<code>$1</code>');

    // Headers
    html = html.replace(/^### (.*$)/gim, '<h3>$1</h3>');
    html = html.replace(/^## (.*$)/gim, '<h2>$1</h2>');
    html = html.replace(/^# (.*$)/gim, '<h1>$1</h1>');

    // Bold
    html = html.replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>');

    // Italic
    html = html.replace(/\*(.*?)\*/gim, '<em>$1</em>');

    // Links
    html = html.replace(/\[(.*?)\]\((.*?)\)/gim, '<a href="$2">$1</a>');

    // Unordered lists
    html = html.replace(/^\- (.*$)/gim, '<li>$1</li>');
    html = html.replace(/(<li>.*<\/li>)/s, '<ul>$1</ul>');

    // Line breaks
    html = html.replace(/\n/gim, '<br>');

    return html;
  };

  const insertMarkdown = (syntax) => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = markdown.substring(start, end);
    let newText = '';
    let cursorPos = start;

    switch (syntax) {
      case 'bold':
        newText = markdown.substring(0, start) + `**${selectedText || 'bold text'}**` + markdown.substring(end);
        cursorPos = start + 2;
        break;
      case 'italic':
        newText = markdown.substring(0, start) + `*${selectedText || 'italic text'}*` + markdown.substring(end);
        cursorPos = start + 1;
        break;
      case 'heading':
        newText = markdown.substring(0, start) + `# ${selectedText || 'Heading'}` + markdown.substring(end);
        cursorPos = start + 2;
        break;
      case 'link':
        newText = markdown.substring(0, start) + `[${selectedText || 'link text'}](url)` + markdown.substring(end);
        cursorPos = start + 1;
        break;
      case 'list':
        newText = markdown.substring(0, start) + `- ${selectedText || 'list item'}` + markdown.substring(end);
        cursorPos = start + 2;
        break;
      default:
        return;
    }

    setMarkdown(newText);

    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(cursorPos, cursorPos);
    }, 0);
  };

  const toolbarButtons = [
    { label: 'B', action: 'bold', title: 'Bold' },
    { label: 'I', action: 'italic', title: 'Italic' },
    { label: 'H', action: 'heading', title: 'Heading' },
    { label: '🔗', action: 'link', title: 'Link' },
    { label: '•', action: 'list', title: 'List' }
  ];

  return (
    <div
      className={`markdown-editor ${p}`}
      style={{
        width: '100%',
        minHeight: `${minHeight}px`,
        border: `1px solid ${borderColor}`,
        borderRadius: '4px',
        overflow: 'hidden',
        backgroundColor: editorBackground,
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
      }}
    >
      {showToolbar && (
        <div style={{
          display: 'flex',
          gap: '4px',
          padding: '8px',
          backgroundColor: previewBackground,
          borderBottom: `1px solid ${borderColor}`
        }}>
          {toolbarButtons.map((btn) => (
            <button
              key={btn.action}
              className={`${p}-btn`}
              onClick={() => insertMarkdown(btn.action)}
              title={btn.title}
              aria-label={btn.title}
              style={{
                padding: '6px 12px',
                backgroundColor: 'transparent',
                border: `1px solid ${borderColor}`,
                borderRadius: '4px',
                color: textColor,
                fontSize: '14px',
                fontWeight: '500',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'all 150ms ease-out',
                fontFamily: btn.action === 'italic' ? 'Georgia, serif' : 'inherit',
                fontStyle: btn.action === 'italic' ? 'italic' : 'normal'
              }}
              onMouseEnter={(e) => {
                if (!prefersReducedMotion) {
                  e.currentTarget.style.backgroundColor = borderColor;
                }
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.backgroundColor = 'transparent';
              }}
            >
              {btn.label}
            </button>
          ))}
        </div>
      )}

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
        minHeight: `${minHeight - (showToolbar ? 41 : 0)}px`
      }}>
        {/* Editor Pane */}
        <div style={{
          position: 'relative',
          borderRight: `1px solid ${borderColor}`
        }}>
          <textarea
            ref={textareaRef}
            value={markdown}
            onChange={(e) => setMarkdown(e.target.value)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
            placeholder={placeholderText}
            aria-label="Markdown source"
            style={{
              width: '100%',
              height: '100%',
              minHeight: `${minHeight - (showToolbar ? 41 : 0)}px`,
              padding: `${editorPadding}px`,
              backgroundColor: editorBackground,
              color: textColor,
              fontSize: `${editorFontSize}px`,
              lineHeight: lineHeight,
              fontFamily: "'Monaco', 'Menlo', 'Ubuntu Mono', 'Consolas', monospace",
              border: 'none',
              outline: isFocused ? `2px solid ${accentColor}` : 'none',
              outlineOffset: '-2px',
              resize: 'none',
              transition: prefersReducedMotion ? 'none' : 'outline 200ms ease-out'
            }}
          />
        </div>

        {/* Preview Pane */}
        <div aria-label="Preview" style={{
          padding: `${previewPadding}px`,
          backgroundColor: previewBackground,
          color: textColor,
          fontSize: `${previewFontSize}px`,
          lineHeight: lineHeight,
          fontFamily: 'Georgia, "Times New Roman", serif',
          overflowY: 'auto',
          transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out'
        }}>
          <div 
            dangerouslySetInnerHTML={{ __html: parseMarkdown(markdown) }}
            style={{
              wordWrap: 'break-word'
            }}
          />
        </div>
      </div>

      <style>{`
        .${p} h1 {
          font-size: 32px;
          font-weight: 600;
          margin: 0 0 16px 0;
          color: ${textColor};
        }
        .${p} h2 {
          font-size: 24px;
          font-weight: 600;
          margin: 24px 0 12px 0;
          color: ${textColor};
        }
        .${p} h3 {
          font-size: 20px;
          font-weight: 600;
          margin: 20px 0 8px 0;
          color: ${textColor};
        }
        .${p} strong {
          font-weight: 600;
          color: ${textColor};
        }
        .${p} em {
          font-style: italic;
        }
        .${p} a {
          color: ${accentColor};
          text-decoration: underline;
        }
        .${p} a:hover {
          opacity: 0.8;
        }
        .${p} ul {
          margin: 16px 0;
          padding-left: 24px;
        }
        .${p} li {
          margin: 8px 0;
          list-style-type: disc;
        }
        .${p} textarea::placeholder {
          color: #6B7280;
          opacity: 1;
        }
        .${p} pre {
          background-color: ${borderColor}50;
          padding: 16px;
          border-radius: 6px;
          overflow-x: auto;
          margin: 16px 0;
        }
        .${p} pre code {
          font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Consolas', monospace;
          font-size: 14px;
          color: ${textColor};
        }
        .${p} code:not(pre code) {
          background-color: ${borderColor}50;
          padding: 2px 6px;
          border-radius: 4px;
          font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Consolas', monospace;
          font-size: 0.9em;
        }
        .${p}-btn:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { transition: none !important; }
        }
      `}</style>
    </div>
  );
}

forms-multistepwizard:
// Component #10: Multi-Step Form Wizard
const MANIFEST = {
  "type": "Forms.MultiStepWizard",
  "description": "Sophisticated multi-step form with validation, conditional logic, and smooth transitions",
  "editorElement": {
    "selector": ".form-wizard",
    "displayName": "Multi-Step Form Wizard",
    "archetype": "container",
    "data": {
      "step1Title": { "dataType": "text", "displayName": "Step 1 Title", "defaultValue": "Personal Information", "group": "Content" },
      "step2Title": { "dataType": "text", "displayName": "Step 2 Title", "defaultValue": "Business Details", "group": "Content" },
      "step3Title": { "dataType": "text", "displayName": "Step 3 Title", "defaultValue": "Preferences", "group": "Content" },
      "step4Title": { "dataType": "text", "displayName": "Step 4 Title", "defaultValue": "Review & Submit", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background", "defaultValue": "#FFFFFF", "group": "Colors" },
      "primaryColor": { "dataType": "color", "displayName": "Primary Color", "defaultValue": "#495057", "group": "Colors" },
      "errorColor": { "dataType": "color", "displayName": "Error Color", "defaultValue": "#DC2626", "group": "Colors" },
      "successColor": { "dataType": "color", "displayName": "Success Color", "defaultValue": "#2D7D3E", "group": "Colors" },
      "borderColor": { "dataType": "color", "displayName": "Border Color", "defaultValue": "#E9ECEF", "group": "Colors" },
      "inputBg": { "dataType": "color", "displayName": "Input Background", "defaultValue": "#F8F9FA", "group": "Colors" },
      "textColor": { "dataType": "color", "displayName": "Text Color", "defaultValue": "#212529", "group": "Colors" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config }) {
  const [currentStep, setCurrentStep] = useState(1);
  const [direction, setDirection] = useState('forward');
  const [formData, setFormData] = useState({
    firstName: '', lastName: '', email: '', phone: '',
    company: '', industry: '', employees: '',
    newsletter: false, notifications: true,
    businessType: ''
  });
  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  const uid = React.useMemo(() => 'fwz' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const totalSteps = 4;

  const validate = (field, value) => {
    switch (field) {
      case 'email':
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value) ? '' : 'Invalid email';
      case 'phone':
        return /^\d{10}$/.test(value.replace(/\D/g, '')) ? '' : 'Invalid phone (10 digits)';
      case 'firstName':
      case 'lastName':
      case 'company':
        return value.trim().length > 0 ? '' : 'This field is required';
      default:
        return '';
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (touched[field]) {
      const error = validate(field, value);
      setErrors(prev => ({ ...prev, [field]: error }));
    }
  };

  const handleBlur = (field) => {
    setTouched(prev => ({ ...prev, [field]: true }));
    const error = validate(field, formData[field]);
    setErrors(prev => ({ ...prev, [field]: error }));
  };

  const canProceed = (step) => {
    switch (step) {
      case 1:
        return !validate('firstName', formData.firstName) && 
               !validate('lastName', formData.lastName) && 
               !validate('email', formData.email);
      case 2:
        return !validate('company', formData.company) && formData.industry;
      case 3:
        return true;
      default:
        return true;
    }
  };

  const nextStep = () => {
    if (canProceed(currentStep) && currentStep < totalSteps) {
      setDirection('forward');
      setCurrentStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 1) {
      setDirection('backward');
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = () => {
    setIsSubmitted(true);
  };

  const renderStepContent = () => {
