function Component({ config = {} }) {
  // Config
  const title = config?.title || "Set up your workspace";
  const primaryColor = config?.primaryColor || "#2563EB";
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const borderRadius = parseInt(config?.borderRadius || "12");

  const steps = [
    config?.step1Title || "Account Details",
    config?.step2Title || "Workspace Info",
    config?.step3Title || "Personalize",
    config?.step4Title || "Review"
  ];

  // State
  const [currentStep, setCurrentStep] = React.useState(0);
  const [direction, setDirection] = React.useState(1); // 1 = forward, -1 = back
  const [isAnimating, setIsAnimating] = React.useState(false);
  const [errors, setErrors] = React.useState({});
  const [touched, setTouched] = React.useState({});

  const uid = React.useMemo(() => 'sob' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  // Form Data State
  const [formData, setFormData] = React.useState({
    fullName: '',
    email: '',
    workspaceName: '',
    teamSize: '1-10',
    role: 'Developer',
    goals: ['Project Management']
  });

  // Derived Values
  const progress = ((currentStep + 1) / steps.length) * 100;

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const validateField = (field, value) => {
    switch (field) {
      case 'fullName':
        return value.trim() ? '' : 'Full name is required';
      case 'email':
        if (!value.trim()) return 'Email address is required';
        return emailRegex.test(value) ? '' : 'Enter a valid email address';
      case 'workspaceName':
        return value.trim() ? '' : 'Workspace name is required';
      default:
        return '';
    }
  };

  const stepFields = [['fullName', 'email'], ['workspaceName'], [], []];

  const validateStep = (step) => {
    const fields = stepFields[step];
    const newErrors = {};
    fields.forEach(field => {
      const error = validateField(field, formData[field]);
      if (error) newErrors[field] = error;
    });
    setErrors(prev => ({ ...prev, ...newErrors }));
    setTouched(prev => {
      const next = { ...prev };
      fields.forEach(field => { next[field] = true; });
      return next;
    });
    return Object.keys(newErrors).length === 0;
  };

  // Handlers
  const handleNext = () => {
    if (!validateStep(currentStep)) return;
    if (currentStep < steps.length - 1) {
      setDirection(1);
      if (prefersReducedMotion) {
        setCurrentStep(prev => prev + 1);
        return;
      }
      setIsAnimating(true);
      setTimeout(() => {
        setCurrentStep(prev => prev + 1);
        setIsAnimating(false);
      }, 300);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setDirection(-1);
      if (prefersReducedMotion) {
        setCurrentStep(prev => prev - 1);
        return;
      }
      setIsAnimating(true);
      setTimeout(() => {
        setCurrentStep(prev => prev - 1);
        setIsAnimating(false);
      }, 300);
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: validateField(field, value) }));
    }
  };

  const handleBlur = (field) => {
    setTouched(prev => ({ ...prev, [field]: true }));
    setErrors(prev => ({ ...prev, [field]: validateField(field, formData[field]) }));
  };

  const toggleGoal = (goal) => {
    setFormData(prev => {
      const goals = prev.goals.includes(goal)
        ? prev.goals.filter(g => g !== goal)
        : [...prev.goals, goal];
      return { ...prev, goals };
    });
  };

  // Styles
  const labelStyle = {
    display: 'block',
    fontSize: '13px',
    fontWeight: '500',
    color: '#374151',
    marginBottom: '6px',
    marginTop: '16px'
  };

  const inputStyle = {
    width: '100%',
    padding: '10px 12px',
    fontSize: '14px',
    border: '1px solid #E5E7EB',
    borderRadius: '6px',
    outline: 'none',
    transition: 'border-color 0.2s, box-shadow 0.2s',
    color: '#1F2937'
  };

  // Render Steps
  const renderStepContent = () => {
    switch (currentStep) {
      case 0: // Account
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>Welcome! First things first.</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>Create your profile to get started.</p>
            </div>

            <label htmlFor={`${p}-fullName`} style={labelStyle}>Full Name</label>
            <input
              id={`${p}-fullName`}
              type="text"
              placeholder="Jane Doe"
              value={formData.fullName}
              onChange={(e) => handleChange('fullName', e.target.value)}
              onBlur={(e) => { e.target.style.borderColor = errors.fullName ? '#DC2626' : '#E5E7EB'; handleBlur('fullName'); }}
              aria-invalid={!!(errors.fullName && touched.fullName)}
              aria-describedby={errors.fullName && touched.fullName ? `${p}-fullName-error` : undefined}
              style={{ ...inputStyle, border: `1px solid ${errors.fullName && touched.fullName ? '#DC2626' : '#E5E7EB'}` }}
              onFocus={(e) => e.target.style.borderColor = primaryColor}
            />
            {errors.fullName && touched.fullName && (
              <div id={`${p}-fullName-error`} role="alert" style={{ fontSize: '12px', color: '#DC2626', marginTop: '4px' }}>{errors.fullName}</div>
            )}

            <label htmlFor={`${p}-email`} style={labelStyle}>Email Address</label>
            <input
              id={`${p}-email`}
              type="email"
              placeholder="jane@company.com"
              value={formData.email}
              onChange={(e) => handleChange('email', e.target.value)}
              onBlur={(e) => { e.target.style.borderColor = errors.email ? '#DC2626' : '#E5E7EB'; handleBlur('email'); }}
              aria-invalid={!!(errors.email && touched.email)}
              aria-describedby={errors.email && touched.email ? `${p}-email-error` : undefined}
              style={{ ...inputStyle, border: `1px solid ${errors.email && touched.email ? '#DC2626' : '#E5E7EB'}` }}
              onFocus={(e) => e.target.style.borderColor = primaryColor}
            />
            {errors.email && touched.email && (
              <div id={`${p}-email-error`} role="alert" style={{ fontSize: '12px', color: '#DC2626', marginTop: '4px' }}>{errors.email}</div>
            )}
          </div>
        );

      case 1: // Workspace
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>Name your workspace.</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>You can always change this later.</p>
            </div>

            <label htmlFor={`${p}-workspaceName`} style={labelStyle}>Workspace Name</label>
            <input
              id={`${p}-workspaceName`}
              type="text"
              placeholder="Acme Corp"
              value={formData.workspaceName}
              onChange={(e) => handleChange('workspaceName', e.target.value)}
              onFocus={(e) => e.target.style.borderColor = primaryColor}
              onBlur={(e) => { e.target.style.borderColor = errors.workspaceName ? '#DC2626' : '#E5E7EB'; handleBlur('workspaceName'); }}
              aria-invalid={!!(errors.workspaceName && touched.workspaceName)}
              aria-describedby={errors.workspaceName && touched.workspaceName ? `${p}-workspaceName-error` : undefined}
              style={{ ...inputStyle, border: `1px solid ${errors.workspaceName && touched.workspaceName ? '#DC2626' : '#E5E7EB'}` }}
            />
            {errors.workspaceName && touched.workspaceName && (
              <div id={`${p}-workspaceName-error`} role="alert" style={{ fontSize: '12px', color: '#DC2626', marginTop: '4px' }}>{errors.workspaceName}</div>
            )}

            <label htmlFor={`${p}-teamSize`} style={labelStyle}>Team Size</label>
            <div style={{ position: 'relative' }}>
              <select
                id={`${p}-teamSize`}
                value={formData.teamSize}
                onChange={(e) => handleChange('teamSize', e.target.value)}
                style={{ ...inputStyle, appearance: 'none', background: 'white' }}
                onFocus={(e) => e.target.style.borderColor = primaryColor}
                onBlur={(e) => e.target.style.borderColor = '#E5E7EB'}
              >
                <option value="1-10">1-10 Employees</option>
                <option value="11-50">11-50 Employees</option>
                <option value="50-200">50-200 Employees</option>
                <option value="200+">200+ Employees</option>
              </select>
              <div aria-hidden="true" style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#6B7280', fontSize: '10px' }}>▼</div>
            </div>
          </div>
        );

      case 2: // Personalize
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>How will you use it?</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>Select all that apply.</p>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {['Project Management', 'CRM', 'Software Development', 'Marketing'].map(goal => (
                <button
                  key={goal}
                  className={`${p}-btn`}
                  aria-pressed={formData.goals.includes(goal)}
                  onClick={() => toggleGoal(goal)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    padding: '12px',
                    borderRadius: '8px',
                    border: `1px solid ${formData.goals.includes(goal) ? primaryColor : '#E5E7EB'}`,
                    backgroundColor: formData.goals.includes(goal) ? `${primaryColor}10` : 'white',
                    cursor: 'pointer',
                    transition: 'border-color 0.2s, background-color 0.2s',
                    textAlign: 'left'
                  }}
                >
                  <div style={{
                    width: '18px',
                    height: '18px',
                    borderRadius: '4px',
                    border: `1px solid ${formData.goals.includes(goal) ? primaryColor : '#D1D5DB'}`,
                    backgroundColor: formData.goals.includes(goal) ? primaryColor : 'transparent',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    marginRight: '12px',
                    color: 'white',
                    fontSize: '12px'
                  }}>
                    {formData.goals.includes(goal) && <span aria-hidden="true">✓</span>}
                  </div>
                  <span style={{ fontSize: '14px', color: '#374151', fontWeight: '500' }}>{goal}</span>
                </button>
              ))}
            </div>
          </div>
        );

      case 3: // Review
        return (
          <div>
            <div style={{ marginBottom: '24px' }}>
              <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', margin: '0 0 4px 0' }}>Review & Launch</h3>
              <p style={{ fontSize: '14px', color: '#6B7280', margin: 0 }}>Please verify your details.</p>
            </div>

            <div style={{ backgroundColor: '#F9FAFB', borderRadius: '8px', padding: '16px', border: '1px solid #F3F4F6' }}>
              {[
                { label: 'Name', value: formData.fullName || 'Not provided' },
                { label: 'Email', value: formData.email || 'Not provided' },
                { label: 'Workspace', value: formData.workspaceName || 'Not provided' },
                { label: 'Team Size', value: formData.teamSize },
                { label: 'Goals', value: formData.goals.join(', ') || 'None selected' }
              ].map((item, i) => (
                <div key={i} style={{ marginBottom: i === 4 ? 0 : '12px', paddingBottom: i === 4 ? 0 : '12px', borderBottom: i === 4 ? 'none' : '1px solid #E5E7EB' }}>
                  <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '0.05em', color: '#9CA3AF', marginBottom: '2px' }}>{item.label}</div>
                  <div style={{ fontSize: '14px', color: '#1F2937', fontWeight: '500' }}>{item.value}</div>
                </div>
              ))}
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div className={`onboarding-wizard ${p}`} style={{
      width: '100%',
      minHeight: '600px',
      backgroundColor: '#F3F4F6',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px',
      fontFamily: 'system-ui, -apple-system, sans-serif'
    }}>
      <style>{`
        .${p}-btn:focus-visible {
          outline: 2px solid ${primaryColor};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <div style={{
        width: '100%',
        maxWidth: '480px',
        backgroundColor: backgroundColor,
        borderRadius: `${borderRadius}px`,
        boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)',
        overflow: 'hidden'
      }}>
        {/* Progress Header */}
        <div style={{ padding: '32px 32px 0 32px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px' }}>
            <span style={{ fontSize: '12px', fontWeight: '600', color: primaryColor, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              Step {currentStep + 1} of {steps.length}
            </span>
            <span style={{ fontSize: '12px', fontWeight: '600', color: '#9CA3AF' }}>
              {steps[currentStep]}
            </span>
          </div>

          <div style={{ width: '100%', height: '6px', backgroundColor: '#F3F4F6', borderRadius: '3px', overflow: 'hidden' }}>
            <div style={{
              width: `${progress}%`,
              height: '100%',
              backgroundColor: primaryColor,
              borderRadius: '3px',
              transition: 'width 0.4s cubic-bezier(0.4, 0, 0.2, 1)'
            }} />
          </div>
        </div>

        {/* Content Area */}
        <div style={{ 
          padding: '32px',
          minHeight: '380px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between'
        }}>
          {/* Animated Content Wrapper */}
          <div style={{
            opacity: isAnimating && !prefersReducedMotion ? 0 : 1,
            transform: isAnimating && !prefersReducedMotion ? `translateX(${direction * -10}px)` : 'translateX(0)',
            transition: 'opacity 0.3s ease, transform 0.3s ease',
            flex: 1
          }}>
            {!isAnimating && renderStepContent()}
          </div>

          {/* Navigation Buttons */}
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '32px', paddingTop: '24px', borderTop: '1px solid #F3F4F6' }}>
            <button
              className={`${p}-btn`}
              onClick={handleBack}
              disabled={currentStep === 0}
              style={{
                background: 'none',
                border: 'none',
                color: currentStep === 0 ? '#D1D5DB' : '#6B7280',
                fontWeight: '500',
                fontSize: '14px',
                cursor: currentStep === 0 ? 'not-allowed' : 'pointer',
                padding: '8px 16px',
                borderRadius: '6px',
                transition: 'color 0.2s'
              }}
              onMouseEnter={(e) => { if(currentStep !== 0) e.target.style.color = '#111827' }}
              onMouseLeave={(e) => { if(currentStep !== 0) e.target.style.color = '#6B7280' }}
            >
              Back
            </button>

            <button
              className={`${p}-btn`}
              onClick={handleNext}
              style={{
                backgroundColor: primaryColor,
                border: 'none',
                color: '#FFFFFF',
                fontWeight: '500',
                fontSize: '14px',
                padding: '10px 24px',
                borderRadius: '6px',
                cursor: 'pointer',
                boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.05)',
                transition: 'background-color 0.2s',
                display: 'flex',
                alignItems: 'center'
              }}
              onMouseEnter={(e) => e.target.style.opacity = '0.9'}
              onMouseLeave={(e) => e.target.style.opacity = '1'}
            >
              {currentStep === steps.length - 1 ? 'Launch Workspace' : 'Continue'} 
              {currentStep !== steps.length - 1 && <span style={{ marginLeft: '6px' }}>→</span>}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

