const MANIFEST = {
  "type": "Form.Conversational",
  "description": "Mad-libs style conversational contact form",
  "editorElement": {
    "selector": ".conversational-form",
    "displayName": "Conversational Form",
    "archetype": "container",
    "data": {
      "introText": { "dataType": "text", "displayName": "Intro Text", "defaultValue": "Hello, my name is", "group": "Content" },
      "fromText": { "dataType": "text", "displayName": "From Text", "defaultValue": "and I'm from", "group": "Content" },
      "helpText": { "dataType": "text", "displayName": "Help Text", "defaultValue": "I'm looking for help with", "group": "Content" },
      "reachText": { "dataType": "text", "displayName": "Reach Text", "defaultValue": "You can reach me at", "group": "Content" },
      "services": { "dataType": "text", "displayName": "Services (comma-separated)", "defaultValue": "Web Design,Branding,Development", "group": "Content" },
      "submitButtonText": { "dataType": "text", "displayName": "Submit Button Text", "defaultValue": "Send Request", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "primaryColor": { "dataType": "color", "displayName": "Primary Color", "defaultValue": "#111111", "group": "Colors" }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const intro = config?.introText || "Hello, my name is";
  const fromText = config?.fromText || "and I'm from";
  const helpText = config?.helpText || "I'm looking for help with";
  const reachText = config?.reachText || "You can reach me at";
  const services = String(config?.services || 'Web Design,Branding,Development').split(',').map(s => s.trim()).filter(Boolean);
  const submitButtonText = config?.submitButtonText || "Send Request";
  const bg = config?.backgroundColor || "#FFFFFF";
  const primary = config?.primaryColor || "#111111";

  const uid = React.useMemo(() => 'cfm' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const [submitted, setSubmitted] = React.useState(false);

  const inputStyle = {
    border: 'none',
    borderBottom: `2px solid ${primary}30`,
    fontSize: 'clamp(24px, 4vw, 48px)',
    fontFamily: 'inherit',
    color: primary,
    background: 'transparent',
    padding: '0 10px 10px 0',
    margin: '0 10px',
    outline: 'none',
    width: 'auto',
    minWidth: '200px',
    maxWidth: '100%',
    transition: 'border-color 0.3s ease'
  };

  const focusStyle = (e) => e.target.style.borderBottomColor = primary;
  const blurStyle = (e) => e.target.style.borderBottomColor = `${primary}30`;

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <div className={p} style={{
      backgroundColor: bg,
      minHeight: '80vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '40px',
      fontFamily: 'Inter, sans-serif'
    }}>
      <style>{`
        .${p}-field:focus-visible, .${p}-submit:focus-visible {
          outline: 2px solid ${primary};
          outline-offset: 3px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { transition: none !important; }
        }
      `}</style>
      {submitted ? (
        <div role="status" style={{ fontSize: 'clamp(24px, 4vw, 40px)', color: primary, fontWeight: '300', textAlign: 'center', maxWidth: '700px' }}>
          Thanks! Your request has been sent — we'll be in touch soon.
        </div>
      ) : (
      <form onSubmit={handleSubmit} style={{ maxWidth: '900px', lineHeight: '1.6' }}>
        <div style={{
          fontSize: 'clamp(24px, 4vw, 48px)',
          color: primary,
          fontWeight: '300'
        }}>
          {intro}
          <input
            type="text"
            className={`${p}-field`}
            placeholder="your name"
            aria-label="Your name"
            required
            style={inputStyle}
            onFocus={focusStyle}
            onBlur={blurStyle}
          />
          {fromText}
          <input
            type="text"
            className={`${p}-field`}
            placeholder="company/location"
            aria-label="Your company or location"
            style={inputStyle}
            onFocus={focusStyle}
            onBlur={blurStyle}
          />
          .<br/><br/>
          {helpText}
          <select
            className={`${p}-field`}
            aria-label="Service you're looking for help with"
            style={{...inputStyle, cursor: 'pointer', appearance: 'none', borderRadius: 0}}
            onFocus={focusStyle}
            onBlur={blurStyle}
          >
            {services.map(service => (
              <option key={service}>{service}</option>
            ))}
          </select>
          .<br/><br/>
          {reachText}
          <input
            type="email"
            className={`${p}-field`}
            placeholder="your@email.com"
            aria-label="Your email address"
            required
            style={inputStyle}
            onFocus={focusStyle}
            onBlur={blurStyle}
          />
          .
        </div>

        <button
          type="submit"
          className={`${p}-submit`}
          style={{
            marginTop: '60px',
            backgroundColor: primary,
            color: bg,
            border: 'none',
            padding: '20px 60px',
            fontSize: '18px',
            textTransform: 'uppercase',
            letterSpacing: '0.1em',
            cursor: 'pointer',
            borderRadius: '4px',
            transition: 'transform 0.2s ease'
          }}
          onMouseEnter={e => { if (!prefersReducedMotion) e.target.style.transform = 'scale(1.05)'; }}
          onMouseLeave={e => e.target.style.transform = 'scale(1)'}
        >
          {submitButtonText}
        </button>
      </form>
      )}
    </div>
  );
}

