                    {getIcon(service.icon, 22)}
                  </div>
                  <span style={{
                    fontSize: '15px',
                    fontWeight: '400'
                  }}>
                    {service.name}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Clients Section */}
      <section
        style={{
          padding: '80px 40px',
          borderBottom: `1px solid ${borderColor}`
        }}
      >
        <div style={{
          maxWidth: '1200px',
          margin: '0 auto',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: '12px',
            fontWeight: '500',
            letterSpacing: '0.15em',
            color: secondaryTextColor,
            marginBottom: '32px'
          }}>
            הלקוחות שלנו
          </div>
          <div style={{
            display: 'flex',
            flexWrap: 'wrap',
            justifyContent: 'center',
            gap: '16px'
          }}>
            {clients.map((client, index) => (
              <span
                key={index}
                style={{
                  padding: '12px 24px',
                  backgroundColor: cardBackground,
                  border: `1px solid ${borderColor}`,
                  fontSize: '14px',
                  fontWeight: '400',
                  color: secondaryTextColor
                }}
              >
                {client}
              </span>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section
        ref={el => sectionRefs.current[5] = el}
        data-index="5"
        style={{
          padding: '160px 40px',
          textAlign: 'center'
        }}
      >
        <h2 style={{
          fontSize: 'clamp(32px, 6vw, 56px)',
          fontWeight: '300',
          marginBottom: '24px',
          opacity: visibleSections.has(5) ? 1 : 0,
          transform: visibleSections.has(5) ? 'translateY(0)' : 'translateY(30px)',
          transition: 'all 0.6s ease-out'
        }}>
          {config?.ctaTitle || 'מוכנים להתחיל?'}
        </h2>
        <p style={{
          fontSize: '18px',
          color: secondaryTextColor,
          marginBottom: '48px',
          maxWidth: '500px',
          margin: '0 auto 48px',
          opacity: visibleSections.has(5) ? 1 : 0,
          transform: visibleSections.has(5) ? 'translateY(0)' : 'translateY(30px)',
          transition: 'all 0.6s ease-out 0.1s'
        }}>
          {config?.ctaSubtitle || 'צרו קשר לייעוץ חינם והתאמת הפתרון המושלם עבורכם'}
        </p>
        <button
          className={`${p}-cta`}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '12px',
            padding: '18px 40px',
            backgroundColor: accentColor,
            color: backgroundColor,
            border: 'none',
            fontSize: '16px',
            fontWeight: '500',
            cursor: 'pointer',
            transition: 'all 0.3s ease',
            opacity: visibleSections.has(5) ? 1 : 0,
            transform: visibleSections.has(5) ? 'translateY(0)' : 'translateY(30px)',
            transitionDelay: '0.2s'
          }}
          onMouseEnter={(e) => {
            e.target.style.backgroundColor = primaryTextColor;
          }}
          onMouseLeave={(e) => {
            e.target.style.backgroundColor = accentColor;
          }}
        >
          <span>{config?.ctaButtonText || 'דברו איתנו'}</span>
          {getIcon('Phone', 18)}
        </button>
      </section>

      {/* Footer */}
      <footer style={{
        padding: '40px',
        borderTop: `1px solid ${borderColor}`,
        textAlign: 'center'
      }}>
        <div style={{
          fontSize: '14px',
          color: secondaryTextColor
        }}>
          © 2024 {companyName}. כל הזכויות שמורות.
        </div>
      </footer>
    </div>
  );
}

