            <div style={styles.visionContent}>
              <div style={{...styles.sectionLabel, color: 'rgba(255,255,255,0.6)'}}>המשימה שלנו</div>
              <p style={styles.visionText}>"{visionText}"</p>
            </div>
          </div>
        </div>
      </section>

      <section style={styles.productsSection} ref={setSectionRef(4)}>
        <div style={styles.productsHeader}>
          <div>
            <div style={styles.sectionLabel}>המוצרים שלנו</div>
