          </div>
        </div>
        <div style={styles.productsGrid}>
          {products.map((product, index) => (
            <div key={index} style={styles.productCard(index)}>
              <div style={styles.productImageContainer}>
                {productImages[index] && (
                  <img 
                    src={productImages[index].trim()} 
