                    style={styles.productImage}
                  />
                )}
              </div>
              <div style={styles.productNumber}>0{index + 1}</div>
              <div style={styles.productName}>{product.trim()}</div>
            </div>
          ))}
        </div>
      </section>

      <section style={styles.servicesSection} ref={setSectionRef(5)}>
        <div style={styles.servicesContent}>
          <div style={styles.servicesHeader}>
            <div style={{...styles.sectionLabel, color: 'rgba(255,255,255,0.6)'}}>השירותים</div>
            <h2 style={styles.servicesTitle}>מה אנחנו מציעים</h2>
            <p style={styles.servicesText}>
              אנחנו מספקים שירות מקצועי ומלא מהשלב הראשוני ועד לתפעול מלא.
            </p>
          </div>
          <div style={styles.servicesList}>
            {services.map((service, index) => (
              <div key={index} style={styles.serviceItem(index)}>
                <span>{service.trim()}</span>
                <span style={styles.serviceNumber}>0{index + 1}</span>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section style={styles.clientsSection} ref={setSectionRef(6)}>
        <div style={styles.clientsHeader}>
          <div style={styles.sectionLabel}>הלקוחות שלנו</div>
          <h2 style={styles.clientsTitle}>מי סומך עלינו</h2>
        </div>
        <div style={styles.clientsGrid}>
          {clients.map((client, index) => (
            <span key={index} style={styles.clientTag(index)}>{client.trim()}</span>
          ))}
        </div>
      </section>

      <section style={styles.ctaSection} ref={setSectionRef(7)}>
        <img src={ctaImage} alt="" style={styles.ctaImage} />
        <div style={styles.ctaOverlay}>
          <div style={styles.ctaContent}>
            <h2 style={styles.ctaTitleStyle}>{ctaTitle}</h2>
            <button className={`${p}-cta`} style={styles.ctaButtonStyle}>
              {ctaButton}
              <ArrowIcon />
            </button>
          </div>
        </div>
      </section>

      <footer style={styles.footer}>
        <div>{companyName}</div>
        <div>© {new Date().getFullYear()}</div>
      </footer>
    </div>
  );
}

