function Component({ config = {} }) {
  const uid = React.useMemo(() => 'aee' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;

  const prefersReducedMotion = React.useMemo(
    () => typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches,
    []
  );

  const allSections = ['hero', 'mission', 'stats', 'values', 'team', 'clients', 'cta'];

  const [visibleSections, setVisibleSections] = React.useState(
    prefersReducedMotion ? new Set(allSections) : new Set()
  );
  const [hoveredValue, setHoveredValue] = React.useState(null);
  const sectionRefs = React.useRef({});

  React.useEffect(() => {
    const fontId = 'google-font-editorial-elegance';
    if (!document.getElementById(fontId)) {
      const link = document.createElement('link');
      link.id = fontId;
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;1,400&family=Source+Sans+3:wght@300;400;500&family=Cormorant+Garamond:ital,wght@0,400;0,500;1,400&display=swap';
      document.head.appendChild(link);
    }
  }, []);

  const companyName = config?.companyName || "Sullivan & Partners";
  const tagline = config?.tagline || "Crafting brand narratives that resonate across generations";
  const missionTitle = config?.missionTitle || "Our Philosophy";
  const missionText = config?.missionText || "We believe in the power of understated elegance. Every brand has a story worth telling—our role is to find the most authentic way to tell it.";
  const foundedYear = config?.foundedYear || "2008";
  const teamSize = config?.teamSize || "47";
  const projectsCompleted = config?.projectsCompleted || "280+";
  const awardsWon = config?.awardsWon || "34";
  const ctaText = config?.ctaText || "Begin a conversation";

  const backgroundColor = config?.backgroundColor || "#FDFCFA";
  const textPrimary = config?.textPrimary || "#1A1A1A";
  const textSecondary = config?.textSecondary || "#6B6B6B";
  const accentColor = config?.accentColor || "#8B7355";
  const dividerColor = config?.dividerColor || "#E8E4DE";

  const headingFont = config?.headingFont || "'Playfair Display', Georgia, serif";
  const bodyFont = config?.bodyFont || "'Source Sans 3', system-ui, sans-serif";
  const heroFontSize = config?.heroFontSize || 72;

  const values = [
    { title: "Integrity", desc: "Truth in every pixel" },
    { title: "Craft", desc: "Obsessive attention to detail" },
    { title: "Longevity", desc: "Designs that age gracefully" },
    { title: "Partnership", desc: "Collaborative excellence" }
  ];

  const team = [
    { name: "Margaret Sullivan", role: "Founding Partner", initials: "MS" },
    { name: "James Chen", role: "Creative Director", initials: "JC" },
    { name: "Elena Voss", role: "Strategy Lead", initials: "EV" },
    { name: "Thomas Wright", role: "Design Director", initials: "TW" }
  ];

  const clients = ["The Metropolitan", "Ritz-Carlton", "Cartier", "Hermès", "Aston Martin", "Christie's"];

  React.useEffect(() => {
    if (prefersReducedMotion) return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisibleSections(prev => new Set([...prev, entry.target.dataset.section]));
          }
        });
      },
      { threshold: 0.15 }
    );

    Object.values(sectionRefs.current).forEach(ref => {
      if (ref) observer.observe(ref);
    });

    return () => observer.disconnect();
  }, []);

  const isVisible = (section) => visibleSections.has(section);

  return (
    <div className={`about-editorial ${p}`} style={{
      fontFamily: bodyFont,
      backgroundColor,
      color: textPrimary,
      minHeight: '100vh',
      overflowX: 'hidden'
    }}>
      <style>{`
        .${p}-section {
          opacity: 0;
          transform: translateY(40px);
          transition: opacity 0.8s ease-out, transform 0.8s ease-out;
        }
        .${p}-section.visible {
          opacity: 1;
          transform: translateY(0);
        }
        .${p}-divider {
          height: 1px;
          background: ${dividerColor};
          transform: scaleX(0);
          transform-origin: left;
          transition: transform 1s ease-out 0.3s;
        }
        .${p}-section.visible .${p}-divider {
          transform: scaleX(1);
        }
        .${p}-stat {
          transition: transform 0.4s ease;
        }
        .${p}-stat:hover {
          transform: translateY(-4px);
        }
        .${p}-team {
          transition: opacity 0.3s ease;
        }
        .${p}-team:hover {
          opacity: 0.7;
        }
        .${p}-cta {
          transition: all 0.4s ease;
          border: 1px solid ${textPrimary};
        }
        .${p}-cta:hover {
          background: ${textPrimary};
          color: ${backgroundColor};
        }
        .${p}-cta:focus-visible {
          outline: 2px solid ${accentColor};
          outline-offset: 3px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { transition: none !important; }
        }
      `}</style>

      {/* Hero Section */}
      <section 
