          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          padding: '120px 80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <p style={{
          fontFamily: bodyFont,
          fontSize: '13px',
          letterSpacing: '0.2em',
          textTransform: 'uppercase',
          color: textSecondary,
          marginBottom: '40px'
        }}>About {companyName}</p>

        <h1 style={{
          fontFamily: headingFont,
          fontSize: `clamp(36px, 6vw, ${heroFontSize}px)`,
          fontWeight: 400,
          lineHeight: 1.1,
          maxWidth: '900px',
          fontStyle: 'italic'
        }}>{tagline}</h1>

        <div className={`${p}-divider`} style={{ marginTop: '80px', maxWidth: '200px' }} />
      </section>

      {/* Mission Section */}
      <section
        ref={el => sectionRefs.current.mission = el}
        data-section="mission"
        className={`${p}-section ${isVisible('mission') ? 'visible' : ''}`}
        style={{
          padding: '120px 80px',
          maxWidth: '1400px',
          margin: '0 auto',
          display: 'grid',
          gridTemplateColumns: '1fr 2fr',
