          alignItems: 'start'
        }}
      >
        <div>
          <p style={{
            fontSize: '12px',
            letterSpacing: '0.2em',
            textTransform: 'uppercase',
            color: textSecondary
          }}>{missionTitle}</p>
        </div>
        <div>
          <p style={{
            fontFamily: headingFont,
            fontSize: 'clamp(24px, 3vw, 32px)',
            fontWeight: 400,
            lineHeight: 1.6,
            color: textPrimary
          }}>{missionText}</p>
          <p style={{
            marginTop: '40px',
            fontSize: '16px',
            lineHeight: 1.8,
            color: textSecondary,
            maxWidth: '600px'
          }}>
            For over fifteen years, we have partnered with brands who understand that true luxury 
            lies not in ostentation, but in the quiet confidence of exceptional work. Our approach 
            is rooted in listening, understanding, and translating vision into reality.
          </p>
        </div>
      </section>

      {/* Stats Section */}
      <section
        ref={el => sectionRefs.current.stats = el}
        data-section="stats"
        className={`${p}-section ${isVisible('stats') ? 'visible' : ''}`}
        style={{
          padding: '80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <div className={`${p}-divider`} style={{ marginBottom: '60px' }} />
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(4, 1fr)',
          gap: '40px'
        }}>
          {[
            { label: 'Founded', value: foundedYear },
            { label: 'Team Members', value: teamSize },
            { label: 'Projects', value: projectsCompleted },
            { label: 'Awards', value: awardsWon }
          ].map((stat, i) => (
            <div 
              key={i} 
              className={`${p}-stat`}
              onMouseEnter={() => setHoveredValue(i)}
