              style={{
                textAlign: 'center',
                padding: '40px 20px',
                cursor: 'default'
              }}
            >
              <p style={{
                fontFamily: headingFont,
                fontSize: hoveredValue === i ? '56px' : '48px',
                fontWeight: 400,
                color: textPrimary,
                marginBottom: '12px',
                transition: 'font-size 0.3s ease'
              }}>{stat.value}</p>
              <p style={{
                fontSize: '12px',
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                color: textSecondary
              }}>{stat.label}</p>
            </div>
          ))}
        </div>
        <div className={`${p}-divider`} style={{ marginTop: '60px' }} />
      </section>

      {/* Values Section */}
      <section
        ref={el => sectionRefs.current.values = el}
        data-section="values"
        className={`${p}-section ${isVisible('values') ? 'visible' : ''}`}
        style={{
          padding: '120px 80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <p style={{
          fontSize: '12px',
          letterSpacing: '0.2em',
          textTransform: 'uppercase',
          color: textSecondary,
          marginBottom: '60px'
        }}>Our Values</p>

        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: '60px 80px'
        }}>
          {values.map((value, i) => (
            <div key={i} style={{ borderLeft: `1px solid ${dividerColor}`, paddingLeft: '30px' }}>
