      {/* Leadership Section */}
      <section
        ref={el => sectionRefs.current.team = el}
        data-section="team"
        className={`${p}-section ${isVisible('team') ? 'visible' : ''}`}
        style={{
          padding: '120px 80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
