      <section
        ref={el => sectionRefs.current.clients = el}
        data-section="clients"
        className={`${p}-section ${isVisible('clients') ? 'visible' : ''}`}
        style={{
          padding: '120px 80px',
          maxWidth: '1400px',
          margin: '0 auto'
        }}
      >
        <div className={`${p}-divider`} style={{ marginBottom: '60px' }} />
        <p style={{
          fontSize: '12px',
          letterSpacing: '0.2em',
          textTransform: 'uppercase',
          color: textSecondary,
          marginBottom: '40px',
          textAlign: 'center'
        }}>Select Clients</p>

        <div style={{
          display: 'flex',
          justifyContent: 'center',
          flexWrap: 'wrap',
          gap: '20px 60px'
        }}>
          {clients.map((client, i) => (
            <span key={i} style={{
              fontFamily: headingFont,
              fontSize: '18px',
              color: textSecondary,
              fontStyle: 'italic'
            }}>{client}</span>
          ))}
        </div>
      </section>

      {/* CTA Section */}
      <section
        ref={el => sectionRefs.current.cta = el}
        data-section="cta"
        className={`${p}-section ${isVisible('cta') ? 'visible' : ''}`}
        style={{
          padding: '160px 80px',
          textAlign: 'center'
        }}
      >
        <h2 style={{
          fontFamily: headingFont,
          fontSize: 'clamp(32px, 4vw, 48px)',
          fontWeight: 400,
          fontStyle: 'italic',
          marginBottom: '50px',
          maxWidth: '600px',
          margin: '0 auto 50px'
        }}>Let's create something timeless together</h2>

        <button className={`${p}-cta`} style={{
          fontFamily: bodyFont,
          fontSize: '13px',
          letterSpacing: '0.15em',
          textTransform: 'uppercase',
          padding: '18px 48px',
          background: 'transparent',
          color: textPrimary,
          cursor: 'pointer'
        }}>{ctaText}</button>
      </section>

      <footer style={{
        padding: '40px 80px',
        borderTop: `1px solid ${dividerColor}`,
        textAlign: 'center'
      }}>
        <p style={{
          fontSize: '12px',
          color: textSecondary,
          letterSpacing: '0.1em'
        }}>© {new Date().getFullYear()} {companyName}. All rights reserved.</p>
      </footer>
    </div>
  );
}
